"""RT check: load the design's route_line_code and route_quantities_code (pinned blocks, by path),
reproduce the route map from route_line_code's own functions, compare with the design's
route_table.route_map and with the session_computations R-C5/R-C6 embedded items, and
apply PTM-RD3 (bridge n'=22 d=3 and Band H n'=66 d=7) through the revision's evaluate()."""
import importlib.util, io, contextlib, json, sys, yaml, hashlib
S, REPO = sys.argv[1], sys.argv[2]
def load(name):
    spec = importlib.util.spec_from_file_location(name, "%s/design_blocks/%s.py" % (S, name))
    m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m); return m
rlc = load("route_line_code"); rqc = load("route_quantities_code")
buf = io.StringIO()
with contextlib.redirect_stdout(buf):
    rqc.main()
lines = buf.getvalue().splitlines()
rows = [json.loads(l) for l in lines]; rows = [r for r in rows if "cell" in r]
summary_line = [l for l in lines if '"summary"' in l]
d = yaml.safe_load(open(REPO + "/coordination/goals/GOAL-ECDLP2M-001/batches/BATCH-521e9d/design/TASK-20261002-01d26d/revision-design.yaml"))["revision_design"]
rc3_summary = d["session_computations"]["items"]["R-C3"]["output"]["summary_line_verbatim"].strip()
out = {"rqc_lines": len(lines), "rqc_rows": len(rows), "rqc_summary_equals_design_R-C3_summary": (summary_line[0].strip() == rc3_summary) if summary_line else None}
# literal tables vs design-embedded R-C5/R-C6 items
emb = {it["id"]: it for it in d["session_computations"]["items"]["R-C5"]["output"]["items"]}
emb.update({it["id"]: it for it in d["session_computations"]["items"]["R-C6"]["output"]["gcd_items"]})
emb.update({it["id"]: it for it in d["session_computations"]["items"]["R-C6"]["output"]["elim_items"]})
mism = []
for r in rlc.SQRMOD_ITEMS:
    e = emb[r[0]]
    if e.get("exit") != r[3]: mism.append((r[0], "exit", e.get("exit"), r[3]))
    if r[4] == "ok":
        for k, idx in (("seconds_per_squaring_amortized_131", 5), ("seconds_precompute", 6), ("seconds_squaring", 7), ("VmPeak_kB", 8)):
            if e.get(k) != r[idx]: mism.append((r[0], k, e.get(k), r[idx]))
for r in rlc.MUL_ITEMS:
    e = emb[r[0]]
    if r[4] == "ok":
        for k, idx in (("seconds_product", 5), ("VmPeak_kB", 6)):
            if e.get(k) != r[idx]: mism.append((r[0], k, e.get(k), r[idx]))
for r in rlc.GCD_ITEMS:
    e = emb[r[0]]
    if e.get("exit") != r[2]: mism.append((r[0], "exit", e.get("exit"), r[2]))
    if r[3] == "ok":
        for k, idx in (("seconds_gcd", 4), ("VmPeak_kB", 5)):
            if e.get(k) != r[idx]: mism.append((r[0], k, e.get(k), r[idx]))
for r in rlc.ELIM_ITEMS:
    e = emb[r[0]]
    for k, idx in (("seconds_elimination", 4), ("VmPeak_kB", 5)):
        if e.get(k) != r[idx]: mism.append((r[0], k, e.get(k), r[idx]))
out["literal_tables_vs_embedded_items_mismatches"] = mism
verdicts, routes, any_sberl = rlc.route_map(rows, 1.0)
rm = d["route_table"]["route_map"]["census_band_l"]
diff = []
for (cell, dd), route in routes.items():
    if cell.startswith("stage2-bandL"):
        if rm[cell][dd] != route: diff.append((cell, dd, rm[cell][dd], route))
out["band_l_route_map_diffs_vs_route_line_code"] = diff
det = {x["group"]: x for x in d["route_table"]["route_map"]["band_l_a_dense_rows_detail"]}
tdiff = []
for (cell, dd), v in verdicts.items():
    g = "%s/d%d" % (cell, dd)
    if g in det and abs(det[g]["T_A_days"] - v["T_A_days"]) / max(v["T_A_days"], 1e-12) > 1e-4:
        tdiff.append((g, det[g]["T_A_days"], v["T_A_days"]))
out["a_dense_detail_T_A_diffs"] = tdiff
kinds = {}
for r in rows:
    kinds.setdefault(r["kind"], 0); kinds[r["kind"]] += 1
out["row_kinds"] = kinds
out["non_bandL_routes"] = sorted({("%s" % c.split('/')[0], routes[(c, dd)]) for (c, dd) in routes if not c.startswith("stage2")})
# PTM-RD3 through the revision's own evaluate()/route_for()
ptm = {}
for cell, dd in (("stage3-bridge-n22", 3), ("stage4-bandH-n66", 7)):
    row = [r for r in rows if r["cell"] == cell and r["d"] == dd][0]
    v = verdicts[(cell, dd)]
    ptm["%s/d%d" % (cell, dd)] = {"q": row.get("q"), "r": row.get("r"), "B": row["B"], "B_power_form": row.get("B_power_form"), "route": routes[(cell, dd)], "fails": v["fails"], "T_A_days": v["T_A_days"]}
out["PTM-RD3_revision_route_line"] = ptm
# what-if: gcd above-ladder exponent fixed at 2.0 (theory) -> route of every band-L row
orig_fit = rlc.fit
def fit2(points, x):
    if points is rlc.GCD_POINTS and x > max(points)[0]:
        top = max(points); return top[1] * (x / top[0]) ** 2.0, "quadratic"
    return orig_fit(points, x)
rlc.fit = fit2
v2, r2, _ = rlc.route_map(rows, 1.0)
rlc.fit = orig_fit
out["route_flips_if_gcd_exponent_2"] = sorted("%s/d%d: %s -> %s (%.4f d)" % (c, dd, routes[(c, dd)], r2[(c, dd)], v2[(c, dd)]["T_A_days"]) for (c, dd) in routes if routes[(c, dd)] != r2[(c, dd)])
print(json.dumps(out, sort_keys=True, indent=1, default=str))

