#!/usr/bin/env python3
"""RT (TASK-20261002-820856) independent engine benchmark, JRD2 attack (ii).

Written by the red team from the definitions, not from the design's blocks.
Operands: uniformly random monic F_2[X] polynomials of a stated degree from a
declared seed (sha256-derived stream).  No cell, lambda, L or H is used.
RLIMIT_AS = 8 GiB is set inside this process before any engine import.

Usage: rt_bench.py ENGINE OP DEGREE SEED [BLOCK_LOG2]
  ENGINE: int (E-INT: CPython Karatsuba on Kronecker-spread ints),
          np (own numpy rfft engine with block 2^BLOCK_LOG2, default 25),
          dec (own decimal Kronecker engine), gcd (own classical Euclid)
  OP: mul | sqrmod | gcd | xcheck (np vs dec vs int product, bitwise equality)
Verification: exact identity modulo a random irreducible p of degree 127
(independent of the design's degree-89 check) and, for xcheck, bitwise
equality of independent engines' products.
"""
import hashlib, json, os, platform, random, resource, sys, time

AS_LIMIT = 8 * 2 ** 30
P_DEG = 127


def emit(r):
    print(json.dumps(r, sort_keys=True), flush=True)


def loadavg():
    with open("/proc/loadavg") as f:
        return f.read().strip()


def status():
    out = {}
    with open("/proc/self/status") as f:
        for line in f:
            k, _, v = line.partition(":")
            if k in ("VmPeak", "VmHWM"):
                out[k + "_kB"] = int(v.split()[0])
    return out


def rng_for(label):
    return random.Random(int.from_bytes(hashlib.sha256(label.encode()).digest()[:8], "big"))


def monic(rng, d):
    return rng.getrandbits(d) | (1 << d)


# ---------- small exact field arithmetic for verification (degree-127 modulus)
def clmul(x, y):
    r = 0
    while y:
        if y & 1:
            r ^= x
        x <<= 1
        y >>= 1
    return r


def pmod(x, p):
    dp = p.bit_length() - 1
    while x.bit_length() - 1 >= dp:
        x ^= p << (x.bit_length() - 1 - dp)
    return x


def is_irred_prime_deg(p, k):
    # k prime: irreducible iff X^(2^k) = X mod p and p has no linear factor (gcd(X^2-X,p)=1 implied)
    x = 2
    for _ in range(k):
        x = pmod(clmul(x, x), p)
    if x != 2:
        return False
    return (p & 1) == 1 and bin(p).count("1") % 2 == 1


def rand_irred(rng, k):
    while True:
        p = (1 << k) | rng.getrandbits(k) | 1
        if is_irred_prime_deg(p, k):
            return p


def red_big(c, p):
    """c mod p for big c, 16 bits at a time with a table of multiples of p (own code)."""
    if c == 0:
        return 0
    k = p.bit_length() - 1
    tbl = [0] * 65536
    for j in range(16):
        top = 1 << (k + j)
        tbl[1 << j] = top ^ pmod(top, p)
    for t in range(3, 65536):
        lo = t & -t
        if t != lo:
            tbl[t] = tbl[t ^ lo] ^ tbl[lo]
    nw = (c.bit_length() + 15) // 16
    data = c.to_bytes(2 * nw, "big")
    rem = 0
    for i in range(0, 2 * nw, 2):
        rem = (rem << 16) | (data[i] << 8) | data[i + 1]
        rem ^= tbl[rem >> k]
    return rem


def mulmod_small(a, b, p):
    return pmod(clmul(a, b), p)


# ---------- engines
def make_int():
    def mul(a, b):
        if a == 0 or b == 0:
            return 0
        k = min(a.bit_length(), b.bit_length()).bit_length() + 1  # 2^k > min length
        tr = {48: "0" * k, 49: "0" * (k - 1) + "1"}
        x = int(format(a, "b").translate(tr), 2)
        y = int(format(b, "b").translate(tr), 2)
        z = x * y
        del x, y
        s = format(z, "b")
        del z
        return int(s[(len(s) - 1) % k::k], 2)  # lowest bit of each k-bit slot = parity
    return mul, {"engine": "E-INT", "python": sys.version.split()[0]}


def make_dec():
    import decimal
    ctx = decimal.Context(prec=decimal.MAX_PREC, Emax=decimal.MAX_EMAX, Emin=decimal.MIN_EMIN,
                          traps=[decimal.Inexact, decimal.Rounded, decimal.InvalidOperation,
                                 decimal.Overflow])
    par = str.maketrans("0123456789", "0101010101")

    def mul(a, b):
        if a == 0 or b == 0:
            return 0
        k = len(str(min(a.bit_length(), b.bit_length()))) + 0
        tr = {48: "0" * k, 49: "0" * (k - 1) + "1"}
        z = ctx.multiply(decimal.Decimal(format(a, "b").translate(tr)),
                         decimal.Decimal(format(b, "b").translate(tr)))
        s = str(z)
        del z
        return int(s[(len(s) - 1) % k::k].translate(par), 2)
    return mul, {"engine": "E-DEC(rt)", "libmpdec": getattr(decimal, "__libmpdec_version__", "?")}


def make_np(block_log2):
    import numpy as np
    BLK = 2 ** block_log2
    st = {"max_err": 0.0, "blocks": 0, "block": BLK}

    def tobits(x):
        n = x.bit_length()
        raw = np.frombuffer(x.to_bytes((n + 7) // 8, "little"), dtype=np.uint8)
        return np.unpackbits(raw, bitorder="little")[:n]

    def toint(bits):
        return int.from_bytes(np.packbits(bits, bitorder="little").tobytes(), "little")

    def mul(a, b):
        if a == 0 or b == 0:
            return 0
        A, Bb = tobits(a), tobits(b)
        out = np.zeros(A.shape[0] + Bb.shape[0] - 1, dtype=np.uint8)
        for i in range(0, A.shape[0], BLK):
            ab = A[i:i + BLK].astype(np.float64)
            L = 1 << int(ab.shape[0] + min(BLK, Bb.shape[0]) - 1).bit_length()
            fa = np.fft.rfft(ab, L)
            del ab
            for j in range(0, Bb.shape[0], BLK):
                bb = Bb[j:j + BLK].astype(np.float64)
                n = A[i:i + BLK].shape[0] + bb.shape[0] - 1
                fb = np.fft.rfft(bb, L)
                del bb
                fb *= fa
                c = np.fft.irfft(fb, L)[:n]
                del fb
                r = np.rint(c)
                e = float(np.max(np.abs(c - r)))
                del c
                st["blocks"] += 1
                st["max_err"] = max(st["max_err"], e)
                if e >= 0.25:
                    raise ArithmeticError("rounding guard %r" % e)
                out[i + j:i + j + n] ^= (r.astype(np.int64) & 1).astype(np.uint8)
                del r
            del fa
        return toint(out)
    return mul, {"engine": "E-NP(rt)", "numpy": np.__version__, "block": BLK, "stats": st}


def spread_sq(a):
    return int(format(a, "b").translate({48: "00", 49: "01"}), 2)


def rev(x, w):
    return int(format(x, "0%db" % w)[::-1], 2)


def barrett_mu(H, D, mul):
    f = rev(H, D + 1)
    g, prec = 1, 1
    while prec < D + 1:
        prec = min(2 * prec, D + 1)
        m = (1 << prec) - 1
        g = mul(f & m, spread_sq(g) & m) & m
    return rev(g, D + 1)


def gcd_rt(a, b):
    """Classical Euclid written by the red team (same algorithm class as declared)."""
    steps = 0
    if a.bit_length() < b.bit_length():
        a, b = b, a
    while b:
        db = b.bit_length()
        while True:
            la = a.bit_length()
            if la < db:
                break
            a ^= b << (la - db)
            steps += 1
        a, b = b, a
    return a, steps


def main(argv):
    eng, op, dtext, seed = argv[1], argv[2], argv[3], int(argv[4])
    blk = int(argv[5]) if len(argv) > 5 else 25
    D = eval(dtext.replace("^", "**"), {"__builtins__": {}})
    err = None
    try:
        resource.setrlimit(resource.RLIMIT_AS, (AS_LIMIT, AS_LIMIT))
    except Exception as e:
        err = str(e)
    for v in ("OPENBLAS_NUM_THREADS", "OMP_NUM_THREADS", "MKL_NUM_THREADS"):
        os.environ[v] = "1"
    item = "%s/%s/%s" % (eng, op, dtext)
    emit({"kind": "header", "item": item, "degree": D, "seed": seed, "block_log2": blk,
          "python": sys.version, "platform": platform.platform(), "nproc": len(os.sched_getaffinity(0)),
          "loadavg_before": loadavg(), "rlimit_as": list(resource.getrlimit(resource.RLIMIT_AS)),
          "rlimit_error": err})
    rec = {"kind": "result", "item": item}
    t0 = time.perf_counter()
    code = 0
    try:
        label = "rt-820856|%s|%d|%d" % (op, D, seed)
        rng = rng_for(label)
        p = rand_irred(rng_for(label + "|p127"), P_DEG)
        rec["check_modulus_hex"] = format(p, "x")
        if eng == "gcd":
            g0 = monic(rng, 32)
            u, v = monic(rng, D - 32), monic(rng, D - 33)

            def smallmul(g, x):
                r, i = 0, 0
                while g:
                    if g & 1:
                        r ^= x << i
                    g >>= 1
                    i += 1
                return r
            a, b = smallmul(g0, u), smallmul(g0, v)
            s = time.perf_counter()
            g, steps = gcd_rt(a, b)
            rec["seconds_gcd"] = round(time.perf_counter() - s, 3)
            rec["steps"], rec["gcd_degree"] = steps, g.bit_length() - 1
            ok1 = g != 0 and pmod(g, g0) == 0
            ok2 = (g.bit_length() <= 4097) and red_big(a, g) == 0 and red_big(b, g) == 0
            rec["verification"] = {"planted_divides": ok1, "divides_both": ok2}
            code = 0 if (ok1 and ok2) else 4
        else:
            mk = {"int": make_int, "dec": make_dec}.get(eng)
            mul, ver = make_np(blk) if eng == "np" else mk()
            rec["engine_version"] = {k: v for k, v in ver.items() if k != "stats"}
            if op == "mul":
                a, b = monic(rng, D), monic(rng, D)
                s = time.perf_counter()
                c = mul(a, b)
                rec["seconds_product"] = round(time.perf_counter() - s, 3)
                ok = mulmod_small(red_big(a, p), red_big(b, p), p) == red_big(c, p) and \
                    c.bit_length() == a.bit_length() + b.bit_length() - 1
                rec["verified_mod_p127"] = ok
                code = 0 if ok else 4
            elif op == "sqrmod":
                H, A = monic(rng, D), monic(rng, D - 1)
                s = time.perf_counter()
                mu = barrett_mu(H, D, mul)
                rec["seconds_precompute"] = round(time.perf_counter() - s, 3)
                s = time.perf_counter()
                S = spread_sq(A)
                Q = mul(S >> D, mu) >> D
                R = S ^ mul(Q, H)
                rec["seconds_squaring"] = round(time.perf_counter() - s, 3)
                rec["seconds_per_squaring_amortized_131"] = round(
                    rec["seconds_squaring"] + rec["seconds_precompute"] / 131.0, 3)
                vA, vH, vQ, vR = (red_big(x, p) for x in (A, H, Q, R))
                ok = mulmod_small(vA, vA, p) == (mulmod_small(vQ, vH, p) ^ vR) and R.bit_length() < H.bit_length()
                rec["verified_mod_p127"] = ok
                code = 0 if ok else 4
            elif op == "xcheck":
                a, b = monic(rng, D), monic(rng, D)
                s = time.perf_counter()
                c1 = mul(a, b)
                rec["seconds_np"] = round(time.perf_counter() - s, 3)
                mul2, ver2 = make_dec()
                s = time.perf_counter()
                c2 = mul2(a, b)
                rec["seconds_dec"] = round(time.perf_counter() - s, 3)
                rec["bitwise_equal_np_dec"] = c1 == c2
                rec["verified_mod_p127"] = mulmod_small(red_big(a, p), red_big(b, p), p) == red_big(c1, p)
                code = 0 if (c1 == c2 and rec["verified_mod_p127"]) else 4
            if eng == "np":
                rec["np_stats"] = dict(ver["stats"])
    except MemoryError as e:
        rec["status"], code = "MemoryError", 3
    except Exception as e:
        rec["status"], code = "exception %s: %s" % (type(e).__name__, str(e)[:200]), 1
    rec["seconds_wall_item"] = round(time.perf_counter() - t0, 3)
    rec["proc_status"] = status()
    rec["loadavg_after"] = loadavg()
    rec.setdefault("status", "ok" if code == 0 else "fail")
    emit(rec)
    return code


if __name__ == "__main__":
    sys.exit(main(sys.argv))

