"""Engine-rate benchmark for the EXP-QSP-70b731 r1 revision design (TASK-20261002-01d26d).

DESIGN FIGURE ONLY (R-C5). Times ONE product, or ONE modular squaring with its
Barrett precomputation timed separately, of uniformly random F_2[X] polynomials
of a stated degree D drawn from a declared seed, on one engine of the declared
I_indep product engine set:
  np  -- E-NP: numpy real FFT of 0/1 coefficient blocks of at most 2^25
         coefficients, rounded to integers; the largest rounding error is
         recorded and must stay below 0.25 (rounding guard);
  dec -- E-DEC: standard-library decimal (libmpdec) by Kronecker substitution,
         k decimal digits per coefficient with 10^k above every coefficient
         sum, under a context that traps Inexact and Rounded.
Modular squaring: A^2 by bit spreading (linear), then Barrett reduction modulo
a monic H of degree D with mu = X^(2D) div H precomputed by Newton inversion of
the reversed H; Q = ((A^2 div X^D) * mu) div X^D; R = A^2 + Q*H.
RLIMIT_AS = 8 GiB is set inside this process before any engine import. No
operand is a lambda, an L, an H of any cell, a composite iterate or
X^(2^n) - X, and none is built from any declared cell: operands are random
monic polynomials of degree exactly D (D - 1 for the squared residue) from a
seed-derived stream.
Verification: every result is checked exactly by a randomised evaluation
identity modulo a uniformly random irreducible polynomial p of prime degree 89
over F_2 (product: a*b = c and deg c = deg a + deg b; squaring: A^2 = Q*H + R
and deg R < D); a false identity passes with probability at most
deg(E)/(2^89 - 2) <= 2^-58 here, E the nonzero error polynomial (deg E <= 2D).

Usage (importing this module executes nothing):
    python3 engine_bench_code.py ENGINE OP DEGREE SEED
    ENGINE in {np, dec}; OP in {mul, sqrmod}; DEGREE an integer or 'b^e'.
Exit codes: 0 verified; 2 usage; 3 MemoryError (instrument condition);
4 verification failed; 5 rounding guard tripped; 1 any other exception.
"""
import hashlib
import importlib.util
import json
import os
import platform
import random
import resource
import sys
import time
from array import array

AS_LIMIT = 8 * 2 ** 30
NP_BLOCK = 2 ** 25
CHECK_DEGREE = 89
ROUND_GUARD = 0.25
SQ_TABLE = {48: "00", 49: "01"}


class RoundingGuard(Exception):
    pass


def emit(record):
    print(json.dumps(record, sort_keys=True), flush=True)


def read_loadavg():
    try:
        with open("/proc/loadavg", encoding="ascii") as handle:
            return handle.read().strip()
    except OSError as error:
        return "unavailable: %s" % error


def proc_status():
    out = {}
    try:
        with open("/proc/self/status", encoding="utf-8", errors="replace") as handle:
            for line in handle:
                key, _, value = line.partition(":")
                if key in ("VmPeak", "VmHWM", "VmSize", "VmRSS"):
                    out[key + "_kB"] = int(value.split()[0])
    except (OSError, ValueError, IndexError) as error:
        out["error"] = str(error)
    return out


def parse_degree(text):
    if "^" in text:
        base, exponent = text.split("^", 1)
        return int(base) ** int(exponent)
    return int(text)


def stream(label):
    digest = hashlib.sha256(label.encode("utf-8")).digest()
    return random.Random(int.from_bytes(digest[:8], "big"))


def random_monic(rng, degree):
    return rng.getrandbits(degree) | (1 << degree)


def clmul_small(x, y):
    out = 0
    while y:
        if y & 1:
            out ^= x
        x <<= 1
        y >>= 1
    return out


def pmod_small(x, p, k):
    while x.bit_length() > k:
        x ^= p << (x.bit_length() - 1 - k)
    return x


def irreducible_prime_degree(p, k):
    """For prime k: p of degree k is irreducible iff p has no root in F_2 and X^(2^k) = X mod p."""
    if not p & 1 or bin(p).count("1") % 2 == 0:
        return False
    x = 2
    for _ in range(k):
        x = pmod_small(clmul_small(x, x), p, k)
    return x == 2


def random_irreducible(rng, k):
    while True:
        p = (1 << k) | rng.getrandbits(k) | 1
        if irreducible_prime_degree(p, k):
            return p


def reduction_table(p, k):
    """Multiples of p whose bits k..k+15 equal the index: table[t] = t*X^k - (t*X^k mod p)."""
    table = [0] * 65536
    for j in range(16):
        top = 1 << (k + j)
        table[1 << j] = top ^ pmod_small(top, p, k)
    for t in range(3, 65536):
        low = t & -t
        if t != low:
            table[t] = table[t ^ low] ^ table[low]
    return table


def big_mod(c, p, k, table):
    """c mod p for a bit-packed polynomial c of any degree (Horner in base X^16)."""
    if c == 0:
        return 0
    nwords = (c.bit_length() + 15) // 16
    words = array("H")
    words.frombytes(c.to_bytes(2 * nwords, "big"))
    if sys.byteorder == "little":
        words.byteswap()
    rem = 0
    for word in words:
        rem = (rem << 16) | word
        rem ^= table[rem >> k]
    return rem


def check_tools(label):
    p = random_irreducible(stream(label + "|check"), CHECK_DEGREE)
    return p, reduction_table(p, CHECK_DEGREE)


def mulmod_small(x, y, p):
    return pmod_small(clmul_small(x, y), p, CHECK_DEGREE)


def verify_product(a, b, c, p, table):
    start = time.perf_counter()
    va, vb, vc = (big_mod(x, p, CHECK_DEGREE, table) for x in (a, b, c))
    holds = mulmod_small(va, vb, p) == vc
    degree_ok = c.bit_length() == a.bit_length() + b.bit_length() - 1
    return {"identity_holds": holds, "degree_ok": degree_ok, "verified": holds and degree_ok,
            "check_modulus_hex": format(p, "x"),
            "verify_seconds": round(time.perf_counter() - start, 3)}


def verify_sqrmod(A, H, Q, R, p, table):
    start = time.perf_counter()
    va, vh, vq, vr = (big_mod(x, p, CHECK_DEGREE, table) for x in (A, H, Q, R))
    holds = mulmod_small(va, va, p) == (mulmod_small(vq, vh, p) ^ vr)
    degree_ok = R.bit_length() < H.bit_length()
    return {"identity_holds": holds, "degree_ok": degree_ok, "verified": holds and degree_ok,
            "check_modulus_hex": format(p, "x"),
            "verify_seconds": round(time.perf_counter() - start, 3)}


def make_np():
    import numpy as np

    stats = {"max_round_error": 0.0, "block_products": 0, "block": NP_BLOCK}

    def bits_of(x):
        nbits = x.bit_length()
        raw = np.frombuffer(x.to_bytes((nbits + 7) // 8, "little"), dtype=np.uint8)
        return np.unpackbits(raw, bitorder="little")[:nbits]

    def int_of(bits):
        return int.from_bytes(np.packbits(bits, bitorder="little").tobytes(), "little")

    def fft_len(n):
        best = 2
        while best < n:
            best *= 2
        f5 = 1
        while f5 < best:
            f35 = f5
            while f35 < best:
                m = f35
                while m < n:
                    m *= 2
                if m % 2 == 0 and m < best:
                    best = m
                f35 *= 3
            f5 *= 5
        return best

    def mul(a, b):
        if a == 0 or b == 0:
            return 0
        abits = bits_of(a)
        bbits = bits_of(b)
        na, nb = abits.shape[0], bbits.shape[0]
        out = np.zeros(na + nb - 1, dtype=np.uint8)
        lb_max = min(nb, NP_BLOCK)
        for i0 in range(0, na, NP_BLOCK):
            ablk = abits[i0:i0 + NP_BLOCK].astype(np.float64)
            la = ablk.shape[0]
            length = fft_len(la + lb_max - 1)
            fa = np.fft.rfft(ablk, length)
            del ablk
            for j0 in range(0, nb, NP_BLOCK):
                bblk = bbits[j0:j0 + NP_BLOCK].astype(np.float64)
                n = la + bblk.shape[0] - 1
                fb = np.fft.rfft(bblk, length)
                del bblk
                fb *= fa
                c = np.fft.irfft(fb, length)
                del fb
                c = c[:n]
                r = np.rint(c)
                np.subtract(c, r, out=c)
                np.abs(c, out=c)
                err = float(c.max())
                del c
                stats["block_products"] += 1
                if err > stats["max_round_error"]:
                    stats["max_round_error"] = err
                if not err < ROUND_GUARD:
                    raise RoundingGuard("E-NP rounding error %r at block (%d, %d)" % (err, i0, j0))
                np.fmod(r, 2.0, out=r)
                out[i0 + j0:i0 + j0 + n] ^= r.astype(np.uint8)
                del r
            del fa
        return int_of(out)

    return mul, stats, {"engine": "E-NP", "numpy": np.__version__}


def make_dec():
    import decimal

    context = decimal.Context(prec=decimal.MAX_PREC, Emax=decimal.MAX_EMAX,
                              Emin=decimal.MIN_EMIN,
                              traps=[decimal.Inexact, decimal.Rounded, decimal.InvalidOperation,
                                     decimal.Overflow, decimal.DivisionByZero])
    parity = str.maketrans("0123456789", "0101010101")
    stats = {"digits_per_coefficient": []}

    def mul(a, b):
        if a == 0 or b == 0:
            return 0
        k = len(str(min(a.bit_length(), b.bit_length())))
        table = {48: "0" * k, 49: "0" * (k - 1) + "1"}
        if k not in stats["digits_per_coefficient"]:
            stats["digits_per_coefficient"].append(k)
        x = decimal.Decimal(format(a, "b").translate(table))
        y = decimal.Decimal(format(b, "b").translate(table))
        product = context.multiply(x, y)
        del x, y
        text = str(product)
        del product
        return int(text[(len(text) - 1) % k::k].translate(parity), 2)

    return mul, stats, {"engine": "E-DEC", "decimal": decimal.__version__,
                        "libmpdec": getattr(decimal, "__libmpdec_version__", "unknown")}


def square_spread(a):
    if a == 0:
        return 0
    return int(format(a, "b").translate(SQ_TABLE), 2)


def reverse_bits(x, width):
    return int(format(x, "0%db" % width)[::-1], 2)


def barrett_mu(H, D, mul):
    """mu = X^(2D) div H for monic H of degree D, by Newton inversion of rev(H) mod X^(D+1)."""
    f = reverse_bits(H, D + 1)
    g = 1
    precision = 1
    while precision < D + 1:
        precision = min(2 * precision, D + 1)
        mask = (1 << precision) - 1
        g = mul(f & mask, square_spread(g) & mask) & mask
    return reverse_bits(g, D + 1)


def barrett_sqrmod(A, H, D, mu, mul):
    S = square_spread(A)
    Q = mul(S >> D, mu) >> D
    R = S ^ mul(Q, H)
    return Q, R


def main(argv):
    if len(argv) != 5 or argv[1] not in ("np", "dec") or argv[2] not in ("mul", "sqrmod"):
        print(__doc__, file=sys.stderr)
        return 2
    engine_name, op, degree_text = argv[1], argv[2], argv[3]
    degree = parse_degree(degree_text)
    seed = int(argv[4])
    limit_error = None
    try:
        resource.setrlimit(resource.RLIMIT_AS, (AS_LIMIT, AS_LIMIT))
    except (ValueError, OSError) as error:
        limit_error = str(error)
    for name in ("OPENBLAS_NUM_THREADS", "OMP_NUM_THREADS", "MKL_NUM_THREADS"):
        os.environ[name] = "1"
    label = "r1-bench|%s|%d|%d" % (op, degree, seed)
    item = "%s/%s/%s" % (engine_name, op, degree_text)
    try:
        nproc = len(os.sched_getaffinity(0))
    except (AttributeError, OSError):
        nproc = None
    emit({"kind": "header", "item": item, "engine": engine_name, "op": op, "degree": degree,
          "degree_text": degree_text, "seed": seed, "operand_label": label,
          "python": sys.version, "executable": sys.executable,
          "machine": platform.machine(), "platform": platform.platform(),
          "cpu_count": os.cpu_count(), "nproc": nproc, "loadavg_before": read_loadavg(),
          "rlimit_as": list(resource.getrlimit(resource.RLIMIT_AS)), "rlimit_error": limit_error,
          "importable": {name: importlib.util.find_spec(name) is not None
                         for name in ("numpy", "gmpy2", "flint", "scipy", "galois")}})
    record = {"kind": "result", "item": item}
    stats = {}
    wall = time.perf_counter()
    try:
        mul, stats, version = make_np() if engine_name == "np" else make_dec()
        record["engine_version"] = version
        rng = stream(label)
        p, table = check_tools(label)
        if op == "mul":
            a = random_monic(rng, degree)
            b = random_monic(rng, degree)
            emit({"kind": "progress", "item": item, "stage": "operands ready"})
            start = time.perf_counter()
            c = mul(a, b)
            record["seconds_product"] = round(time.perf_counter() - start, 3)
            emit({"kind": "progress", "item": item, "stage": "product done",
                  "seconds_product": record["seconds_product"]})
            record["verification"] = verify_product(a, b, c, p, table)
        else:
            H = random_monic(rng, degree)
            A = random_monic(rng, degree - 1)
            emit({"kind": "progress", "item": item, "stage": "operands ready"})
            start = time.perf_counter()
            mu = barrett_mu(H, degree, mul)
            record["seconds_precompute"] = round(time.perf_counter() - start, 3)
            emit({"kind": "progress", "item": item, "stage": "precompute done",
                  "seconds_precompute": record["seconds_precompute"]})
            start = time.perf_counter()
            Q, R = barrett_sqrmod(A, H, degree, mu, mul)
            record["seconds_squaring"] = round(time.perf_counter() - start, 3)
            record["seconds_per_squaring_amortized_131"] = round(
                record["seconds_squaring"] + record["seconds_precompute"] / 131.0, 3)
            emit({"kind": "progress", "item": item, "stage": "squaring done",
                  "seconds_squaring": record["seconds_squaring"]})
            record["verification"] = verify_sqrmod(A, H, Q, R, p, table)
        verified = record["verification"]["verified"]
        record["status"] = "ok" if verified else "verification_failed"
        code = 0 if verified else 4
    except MemoryError as error:
        record["status"] = "MemoryError"
        record["detail"] = str(error)[:300]
        code = 3
    except RoundingGuard as error:
        record["status"] = "rounding_guard"
        record["detail"] = str(error)
        code = 5
    except Exception as error:
        record["status"] = "exception"
        record["detail"] = "%s: %s" % (type(error).__name__, str(error)[:300])
        code = 1
    record["engine_stats"] = stats
    record["seconds_wall_item"] = round(time.perf_counter() - wall, 3)
    record["peak_rss_bytes"] = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss * 1024
    record["proc_status"] = proc_status()
    record["loadavg_after"] = read_loadavg()
    emit(record)
    return code


if __name__ == "__main__":
    sys.exit(main(sys.argv))

