#!/usr/bin/env python3
"""RT (TASK-20261002-820856) attack (ii): the boundary rows re-evaluated with the red
team's own measurements (measure_log.txt, measure2_log.txt) beside the design's relays.
Rule: DEC-20261002-c01bb7 R-ROUTE-RULE, T_A = G (131 t_sq(B) + t_gcd(B)), 90-day line,
marginal band (30, 270].  Breaking conditions of the plan's attack (ii) are evaluated
literally.  Bound-formula arithmetic and timing arithmetic only."""
import json, math, sys

S = sys.argv[1]
DAY = 86400.0


def results(path):
    out = {}
    for line in open(path, encoding="utf-8", errors="replace"):
        line = line.strip()
        if line.startswith("{") and '"kind": "result"' in line:
            r = json.loads(line)
            out[r["item"]] = r
    return out


mine = {}
mine.update(results(S + "/measure_log.txt"))
mine.update(results(S + "/measure2_log.txt"))

DES_SQ_NP = {"2^16": 0.019, "2^20": 0.466, "2^22": 2.419, "5^10": 6.725, "2^24": 13.99, "5^11": 86.522,
             "6^10": 91.556, "3^17": 321.438, "5^12": 1359.589, "2^28": 1386.139}
DES_SQ_DEC = {"6^10": 242.215, "3^17": 551.673, "2^22": 10.051, "2^20": 2.318}
DES_MUL_NP = {"2^28": 737.071}
DES_GCD = {22: 139.534, 23: 472.09, 24: 1865.691}
DEG = {"2^20": 2 ** 20, "2^22": 2 ** 22, "5^10": 5 ** 10, "2^24": 2 ** 24, "5^11": 5 ** 11, "6^10": 6 ** 10,
       "3^17": 3 ** 17, "5^12": 5 ** 12, "2^28": 2 ** 28}


def g(item, key):
    r = mine.get(item)
    return None if r is None else r.get(key)


rep = {"items": {}, "ratios_mine_over_design": {}}
for item, r in sorted(mine.items()):
    keep = {k: r.get(k) for k in ("status", "seconds_gcd", "steps", "gcd_degree", "seconds_precompute",
                                   "seconds_squaring", "seconds_per_squaring_amortized_131", "seconds_product",
                                   "seconds_np", "seconds_dec", "bitwise_equal_np_dec", "verified_mod_p127",
                                   "loadavg_before", "loadavg_after", "seconds_wall_item")}
    keep["verification"] = r.get("verification")
    keep["engine_stats"] = r.get("engine_stats") or r.get("np_stats")
    keep["VmPeak_kB"] = (r.get("proc_status") or {}).get("VmPeak_kB")
    rep["items"][item] = keep

for k, dv in (("gcd/2^22", DES_GCD[22]), ("gcd/2^23", DES_GCD[23]), ("gcd/2^24", DES_GCD[24])):
    if g(k, "seconds_gcd"):
        rep["ratios_mine_over_design"][k] = round(g(k, "seconds_gcd") / dv, 4)
for deg in ("5^12", "6^10", "3^17"):
    k = "np/sqrmod/" + deg
    if g(k, "seconds_per_squaring_amortized_131"):
        rep["ratios_mine_over_design"][k] = round(g(k, "seconds_per_squaring_amortized_131") / DES_SQ_NP[deg], 4)
if g("dec/sqrmod/6^10", "seconds_per_squaring_amortized_131"):
    rep["ratios_mine_over_design"]["dec/sqrmod/6^10"] = round(g("dec/sqrmod/6^10", "seconds_per_squaring_amortized_131") / DES_SQ_DEC["6^10"], 4)
if g("np/mul/2^28", "seconds_product"):
    rep["ratios_mine_over_design"]["np/mul/2^28"] = round(g("np/mul/2^28", "seconds_product") / DES_MUL_NP["2^28"], 4)

# own gcd ladder (declared gcd, design block) and its top-segment exponent
G_MINE = {k: g("gcd/2^%d" % k, "seconds_gcd") for k in (22, 23, 24)}
have_g24 = G_MINE.get(24) is not None
e_top_mine = math.log(G_MINE[24] / G_MINE[23], 2) if have_g24 and G_MINE.get(23) else None
rep["gcd_top_segment_exponent_mine"] = None if e_top_mine is None else round(e_top_mine, 4)


def t_gcd(B, top, e):
    return top * (B / 2 ** 24) ** e


ROWS = [("stage2-bandL-n10/d4", 4 ** 14, 12, "2^28"), ("stage2-bandL-n11/d5", 5 ** 12, 32, "5^12"),
        ("stage2-bandL-n14/d6", 6 ** 10, 64, "6^10"), ("stage2-bandL-n8/d3", 3 ** 17, 8, "3^17"),
        ("stage2-bandL-n12/d6", 6 ** 11, 64, None), ("stage2-bandL-n14/d7", 7 ** 10, 128, None)]
lines = {}
for name, B, G, lad in ROWS:
    variants = {}
    # squaring time candidates
    sq = {"design_relay": DES_SQ_NP.get(lad) if lad else DES_SQ_NP["2^28"] * (B / 2 ** 28)}
    if lad and g("np/sqrmod/" + lad, "seconds_per_squaring_amortized_131"):
        sq["mine_measured"] = g("np/sqrmod/" + lad, "seconds_per_squaring_amortized_131")
    if lad == "2^28":
        m512 = g("np/sqrmod/5^12", "seconds_per_squaring_amortized_131")
        if m512:
            sq["mine_proxy_5^12_scaled_linear"] = m512 * (2 ** 28 / 5 ** 12)
            sq["mine_proxy_5^12_same_block_regime"] = m512 * (DES_SQ_NP["2^28"] / DES_SQ_NP["5^12"])
        mm = g("np/mul/2^28", "seconds_product")
        if mm:
            sq["mine_proxy_design_sq_x_mul_ratio"] = DES_SQ_NP["2^28"] * mm / DES_MUL_NP["2^28"]
    gd = {}
    gd["design_top_exp_1.9826"] = t_gcd(B, DES_GCD[24], 1.9826) if B > 2 ** 24 else None
    gd["design_exp_2"] = t_gcd(B, DES_GCD[24], 2.0) if B > 2 ** 24 else None
    if have_g24:
        gd["mine_exp_2"] = t_gcd(B, G_MINE[24], 2.0) if B > 2 ** 24 else None
        if e_top_mine:
            gd["mine_top_exp"] = t_gcd(B, G_MINE[24], e_top_mine) if B > 2 ** 24 else None
    for sk, sv in sq.items():
        for gk, gv in gd.items():
            if sv is None or gv is None:
                continue
            ta = G * (131 * sv + gv) / DAY
            variants["%s | %s" % (sk, gk)] = {"T_A_days": round(ta, 3), "route": "A" if ta <= 90 else "S",
                                             "marginal": 30 < ta <= 270}
    lines[name] = {"B": B, "G": G, "design_route": {"stage2-bandL-n10/d4": "A", "stage2-bandL-n11/d5": "S",
                                                    "stage2-bandL-n14/d6": "A", "stage2-bandL-n8/d3": "A",
                                                    "stage2-bandL-n12/d6": "S", "stage2-bandL-n14/d7": "S"}[name],
                   "variants": variants}
rep["rows"] = lines

# plan attack (ii) breaking conditions, literally
brk = []
for name, row in lines.items():
    for vk, v in row["variants"].items():
        if row["design_route"] == "S" and v["T_A_days"] <= 30:
            brk.append("substituted row at most 30 days: %s %s" % (name, vk))
        if row["design_route"] == "A" and v["T_A_days"] > 270:
            brk.append("derivation-(A) row above 270 days: %s %s" % (name, vk))
rep["attack_ii_breaking_conditions_met"] = brk
# E-INT dominance
dom = {}
for deg in ("2^20", "2^22"):
    ei = g("int/sqrmod/" + deg, "seconds_per_squaring_amortized_131")
    if ei:
        dom[deg] = {"E-INT_amortized_s": ei, "E-NP_design_s": DES_SQ_NP[deg], "E-DEC_design_s": DES_SQ_DEC[deg],
                    "E-INT_over_fastest_declared": round(ei / min(DES_SQ_NP[deg], DES_SQ_DEC[deg]), 2)}
rep["e_int_dominance"] = dom
# verification overhead of WO-I-14 (design block's verify_seconds) relative to one squaring
for deg in ("5^12", "6^10", "3^17"):
    r = mine.get("np/sqrmod/" + deg)
    if r and isinstance(r.get("verification"), dict):
        vs = r["verification"].get("verify_seconds")
        sqs = r.get("seconds_squaring")
        if vs is not None and sqs:
            rep.setdefault("verification_overhead", {})[deg] = {"verify_seconds": vs, "seconds_squaring": sqs,
                                                                "ratio": round(vs / sqs, 4)}
print(json.dumps(rep, sort_keys=True, indent=1))

