#!/usr/bin/env python3
"""RT (TASK-20261002-820856) PTM-RD4 / PTM-RD5 harness on WO-I-10's trace schema.

Own primitive layer (events {seq, op, ins, out, mats, mats_out, k, label,
after_arith}; TPoly __slots__ (value, token) exactly as interface.primitive_layer
words it), own audit R0..R4 written from the WO-I-10 text, and the design's
reference audit() (code_blocks.trace_audit_demo_code, loaded by path, pinned
sha256) applied to the same events.  Synthetic cells only: field degree n
outside {4, 7, 11, 12, 13, 31, 131}, n <= 19.  No declared cell, no bound
closure file, no RUN id.
"""
import copy, hashlib, importlib.util, json, random, sys

DECLARED_N = {4, 7, 11, 12, 13, 31, 131}


# ------------------------------------------------------------------ F_2[X] ints
def pmul(a, b):
    r = 0
    while b:
        if b & 1:
            r ^= a
        a <<= 1
        b >>= 1
    return r


def pdivmod(a, b):
    if b == 0:
        raise ZeroDivisionError
    q, db = 0, b.bit_length()
    while a.bit_length() >= db:
        s = a.bit_length() - db
        q ^= 1 << s
        a ^= b << s
    return q, a


def pgcd(a, b):
    while b:
        a, b = b, pdivmod(a, b)[1]
    return a


def pderiv(a):
    r, i = 0, 1
    a >>= 1
    while a:
        if (a & 1) and (i & 1):
            r ^= 1 << (i - 1)
        a >>= 1
        i += 1
    return r


def psqrt(a):
    r, i = 0, 0
    while a:
        if a & 1:
            if i & 1:
                raise ArithmeticError("not a square")
            r |= 1 << (i >> 1)
        a >>= 1
        i += 1
    return r


def pcompose(lam, a):
    acc = 0
    for i in range(lam.bit_length() - 1, -1, -1):
        acc = pmul(acc, a) ^ ((lam >> i) & 1)
    return acc


def irreducible(p):
    """Rabin test over F_2 for p of degree k."""
    k = p.bit_length() - 1
    if k < 1:
        return False
    if k == 1:
        return True          # X and X + 1 (fix: the Rabin comparison below assumes k >= 2)

    def frob(m):
        x = 2
        for _ in range(m):
            x = pdivmod(pmul(x, x), p)[1]
        return x
    if frob(k) != 2:
        return False
    ps, m, f = [], k, 2
    while f * f <= m:
        if m % f == 0:
            ps.append(f)
            while m % f == 0:
                m //= f
        f += 1
    if m > 1:
        ps.append(m)
    return all(pgcd(p, frob(k // q) ^ 2) == 1 for q in ps)


def rad_value(f):
    """Squarefree part by trial division (independent of the routes)."""
    res, g = 1, 2
    while f.bit_length() > 1 and 2 * (g.bit_length() - 1) <= f.bit_length() - 1:
        if irreducible(g) and pdivmod(f, g)[1] == 0:
            res = pmul(res, g)
            while pdivmod(f, g)[1] == 0:
                f = pdivmod(f, g)[0]
        g += 1
    if f.bit_length() > 1:
        res = pmul(res, f)
    return res


class Field:
    def __init__(self, n, P):
        assert irreducible(P) and P.bit_length() - 1 == n
        self.n, self.P, self.size = n, P, 1 << n
        order = self.size - 1
        # find a primitive element
        fac, m, f = [], order, 2
        while f * f <= m:
            if m % f == 0:
                fac.append(f)
                while m % f == 0:
                    m //= f
            f += 1
        if m > 1:
            fac.append(m)

        def mulslow(x, y):
            return pdivmod(pmul(x, y), P)[1]

        def powslow(x, e):
            r = 1
            while e:
                if e & 1:
                    r = mulslow(r, x)
                x = mulslow(x, x)
                e >>= 1
            return r
        g = next(c for c in range(2, self.size) if all(powslow(c, order // q) != 1 for q in fac))
        self.exp = [0] * (2 * order)
        self.log = [0] * self.size
        x = 1
        for e in range(order):
            self.exp[e] = self.exp[e + order] = x
            self.log[x] = e
            x = mulslow(x, g)
        self.order = order

    def mul(self, x, y):
        return 0 if (x == 0 or y == 0) else self.exp[self.log[x] + self.log[y]]

    def frob(self, x, k):
        if x == 0:
            return 0
        return self.exp[(self.log[x] * pow(2, k, self.order)) % self.order]

    def ev(self, poly, x):
        if x == 0:
            return poly & 1
        lx, acc, i = self.log[x], 0, 0
        while poly:
            if poly & 1:
                acc ^= self.exp[(i * lx) % self.order]
            poly >>= 1
            i += 1
        return acc

    def roots(self, poly):
        return [x for x in range(self.size) if self.ev(poly, x) == 0]


# ------------------------------------------------------------------ primitive layer
from rt_tpoly import TPoly, TMat
import rt_new_routes


class Prim:
    def __init__(self, field):
        self.field, self.events, self.values, self.matrix_rows = field, [], {}, {}
        self.next, self.arith = 1, False

    def _p(self, v):
        t = self.next
        self.next += 1
        self.values[t] = v
        return TPoly(v, t)

    def _m(self, rows):
        t = self.next
        self.next += 1
        self.matrix_rows[t] = list(rows)
        return TMat(rows, t)

    def _ev(self, op, ins=(), outs=(), mats=(), mats_out=(), **kw):
        if op != "lift":
            self.arith = True
        e = {"seq": len(self.events), "op": op, "ins": [x.token for x in ins], "out": [x.token for x in outs],
             "mats": [m.token for m in mats], "mats_out": [m.token for m in mats_out]}
        e.update(kw)
        self.events.append(e)

    def lift(self, v, label):
        o = self._p(v)
        self._ev("lift", outs=[o], label=label, after_arith=self.arith)
        return o

    def add(self, a, b):
        o = self._p(a.value ^ b.value); self._ev("add", [a, b], [o]); return o

    def mul(self, a, b):
        o = self._p(pmul(a.value, b.value)); self._ev("mul", [a, b], [o]); return o

    def sqr(self, a):
        o = self._p(pmul(a.value, a.value)); self._ev("sqr", [a], [o]); return o

    def shift(self, a, k):
        o = self._p(a.value << k); self._ev("shift", [a], [o], k=k); return o

    def mod(self, a, m):
        o = self._p(pdivmod(a.value, m.value)[1]); self._ev("mod", [a, m], [o]); return o

    def mulmod(self, a, b, m):
        o = self._p(pdivmod(pmul(a.value, b.value), m.value)[1]); self._ev("mulmod", [a, b, m], [o]); return o

    def sqrmod(self, a, m):
        o = self._p(pdivmod(pmul(a.value, a.value), m.value)[1]); self._ev("sqrmod", [a, m], [o]); return o

    def gcd(self, a, b):
        o = self._p(pgcd(a.value, b.value)); self._ev("gcd", [a, b], [o]); return o

    def div_exact(self, a, b):
        q, r = pdivmod(a.value, b.value)
        if r:
            raise ArithmeticError("inexact")
        o = self._p(q); self._ev("div_exact", [a, b], [o]); return o

    def deriv(self, a):
        o = self._p(pderiv(a.value)); self._ev("deriv", [a], [o]); return o

    def sqrt(self, a):
        o = self._p(psqrt(a.value)); self._ev("sqrt", [a], [o]); return o

    def compose(self, lam, a):
        o = self._p(pcompose(lam.value, a.value)); self._ev("compose", [lam, a], [o]); return o

    def degree(self, a):
        self._ev("degree", [a]); return a.value.bit_length() - 1

    def is_zero(self, a):
        self._ev("is_zero", [a]); return a.value == 0

    def equal(self, a, b):
        self._ev("equal", [a, b]); return a.value == b.value

    def mat_rows(self, rows):
        o = self._m([r.value for r in rows]); self._ev("mat_rows", rows, mats_out=[o]); return o

    def mat_add_identity(self, M):
        o = self._m([r ^ (1 << i) for i, r in enumerate(M.rows)]); self._ev("mat_add_identity", mats=[M], mats_out=[o]); return o

    def mat_left_kernel(self, M):
        m = len(M.rows)
        buckets = {}
        for i, row in enumerate(M.rows):
            aug = (row << m) | (1 << i)
            buckets.setdefault(aug.bit_length(), []).append(aug)
        for top in range(2 * m, m, -1):
            grp = buckets.pop(top, None)
            if not grp:
                continue
            piv = grp[0]
            for row in grp[1:]:
                row ^= piv
                buckets.setdefault(row.bit_length(), []).append(row)
        outs = [self._p(r) for k in sorted(buckets) for r in buckets[k]]
        self._ev("mat_left_kernel", mats=[M], outs=outs)
        return outs

    def mat_apply(self, M, v):
        val, c, i = 0, v.value, 0
        while c:
            if c & 1:
                val ^= M.rows[i]
            c >>= 1
            i += 1
        o = self._p(val); self._ev("mat_apply", [v], [o], mats=[M]); return o

    def kroots(self, a):
        self._ev("kroots", [a]); return self.field.roots(a.value)


# ------------------------------------------------------------------ RT audit from WO-I-10 text
def audit_rt(events, values, n_prime, lam, P, Lv, Rv):
    bound = 1 << (n_prime + 1)
    T, MT, viol = {}, {}, []

    def tg(t):
        return T.setdefault(t, {"L": False, "D": False, "K": False, "x": None})

    def lcl(t):
        return tg(t)["L"] or values.get(t) in (Lv, Rv)

    def same(a, b):
        return a == b or (values.get(a) is not None and values.get(a) == values.get(b))

    def xcomb(toks):
        tot, mod = 0, None
        for t in toks:
            x = tg(t)["x"]
            if x is None:
                return None
            tot += x[0]
            if x[1] is not None:
                if mod is not None and not same(mod, x[1]):
                    return None
                mod = x[1]
        return (tot, mod)

    def flag(rule, e, why):
        viol.append({"rule": rule, "seq": e["seq"], "op": e["op"], "why": why})

    for e in events:
        op, ins, outs = e["op"], e["ins"], e["out"]
        if op == "lift":
            lab = e.get("label")
            exp = {"one": 1, "X": 2, "lambda": lam, "modulus_P": P}.get(lab)
            if e.get("after_arith") or exp is None or values.get(outs[0]) != exp:
                flag("R0", e, "lift after arithmetic / bad label or value")
            if lab == "one":
                tg(outs[0])["x"] = (0, None)
            elif lab == "X":
                tg(outs[0])["x"] = (1, None)
        elif op == "add":
            a, b = ins
            if (tg(a)["K"] and values.get(b) == 1) or (tg(b)["K"] and values.get(a) == 1):
                tg(outs[0])["K"] = True
        elif op in ("mul", "sqr"):
            ops = ins if op == "mul" else [ins[0], ins[0]]
            if all(lcl(t) for t in ops):
                tg(outs[0])["L"] = True
            x = xcomb(ops)
            if x is not None:
                tg(outs[0])["x"] = x
        elif op == "shift":
            x = tg(ins[0])["x"]
            if x is not None:
                tg(outs[0])["x"] = (x[0] + e["k"], x[1])
        elif op in ("mod", "mulmod", "sqrmod"):
            m = ins[-1]
            ops = [ins[0], ins[0]] if op == "sqrmod" else ins[:-1]
            if lcl(m):
                for t in set(ops):
                    if not (tg(t)["x"] is not None or tg(t)["K"] or lcl(t)):
                        flag("R3", e, "reduction mod L-class of a non-allowed operand")
            if op == "mod" and tg(ops[0])["K"] and lcl(m):
                tg(outs[0])["K"] = True
            x = xcomb(ops)
            if x is not None and (op == "mod" or x[1] is None or same(x[1], m)):
                tg(outs[0])["x"] = (x[0], m)   # "mod keeps e and sets M"
                if lcl(m) and x[0] >= bound:
                    flag("R1", e, "X^%d modulo an L-class modulus" % x[0])
        elif op == "gcd":
            a, b = ins
            for t, o in ((a, b), (b, a)):
                if lcl(t) and not (lcl(o) or tg(o)["D"] or tg(o)["K"]):
                    flag("R2", e, "gcd of L-class with non-allowed partner")
                    break
            if lcl(a) or lcl(b):
                tg(outs[0])["L"] = True
        elif op in ("div_exact", "sqrt"):
            if lcl(ins[0]):
                tg(outs[0])["L"] = True
        elif op == "deriv":
            if lcl(ins[0]):
                tg(outs[0])["D"] = True
        elif op == "mat_rows":
            xs = [tg(t)["x"] for t in ins]
            ok = bool(ins) and all(x is not None and x[1] is not None for x in xs)
            if ok:
                f = xs[0][1]
                ok = (all(same(x[1], f) for x in xs) and lcl(f) and all(x[0] == 2 * i for i, x in enumerate(xs))
                      and values[f].bit_length() - 1 == len(ins))
            MT[e["mats_out"][0]] = {"Q": ok}
        elif op == "mat_add_identity":
            MT[e["mats_out"][0]] = {"QmI": bool(MT.get(e["mats"][0], {}).get("Q"))}
        elif op == "mat_left_kernel":
            if not MT.get(e["mats"][0], {}).get("QmI"):
                flag("R4", e, "kernel of a matrix other than Q - I")
            for t in outs:
                tg(t)["K"] = True
        elif op in ("mat_apply", "mat_mul"):
            flag("R4", e, op)
    return viol


# ------------------------------------------------------------------ design reference audit
def load_ref(path, pinned):
    src = open(path, "rb").read()
    assert hashlib.sha256(src).hexdigest() == pinned, "reference block digest mismatch"
    spec = importlib.util.spec_from_file_location("trace_audit_demo_code", path)
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    return m


def audit_ref(ref, events, values, n_prime, lam, Lv, Rv):
    evs = []
    for e in events:
        e2 = dict(e)
        if e2["op"] == "mat_left_kernel":
            e2["op"] = "kernel"
        evs.append(e2)
    return ref.audit(evs, values, n_prime, lam, Lv, Rv)


# ------------------------------------------------------------------ routes
def inputs(p, lam):
    return p.lift(1, "one"), p.lift(2, "X"), p.lift(lam, "lambda")


def build_L(p, one, lamt, npr):
    return p.add(p.shift(one, 1 << npr), lamt)


def rad(p, f):
    if p.degree(f) <= 0:
        return f
    d = p.deriv(f)
    if p.is_zero(d):
        return rad(p, p.sqrt(f))
    g = p.gcd(f, d)
    w = p.div_exact(f, g)
    if p.degree(g) == 0:
        return w
    r = rad(p, g)
    return p.div_exact(p.mul(w, r), p.gcd(w, r))


def q_rows(p, one, f):
    rows = [p.mod(one, f)]
    for _ in range(1, p.degree(f)):
        rows.append(p.mod(p.shift(rows[-1], 2), f))
    return rows


def berlekamp(p, one, f):
    if p.degree(f) <= 1:
        return [f]
    ker = p.mat_left_kernel(p.mat_add_identity(p.mat_rows(q_rows(p, one, f))))
    k = len(ker)
    facs = [f]
    for v in ker:
        if len(facs) == k:
            break
        new = []
        for g in facs:
            if p.degree(g) <= 1:
                new.append(g)
                continue
            h = p.gcd(g, p.mod(v, g))
            dh = p.degree(h)
            if 0 < dh < p.degree(g):
                new += [h, p.div_exact(g, h)]
            else:
                new.append(g)
        facs = new
    if len(facs) != k:
        raise ArithmeticError("split incomplete")
    return facs


def composite_H(p, one, X, lamt, n, npr):
    q, r = divmod(n, npr)
    c = X
    for _ in range(q + 1):
        c = p.compose(lamt, c)
    return p.add(p.shift(one, 1 << (npr - r)), c)


def closing_count(field, n, npr, lam, ys):
    q, r = divmod(n, npr)
    cnt = 0
    for y in ys:
        x = y
        for _ in range(q):
            x = field.ev(lam, x)
        if field.frob(x, r) == y and field.frob(x, npr) == field.ev(lam, x):
            cnt += 1
    return cnt


def a_dense_core(p, n, npr, lam):
    one, X, lamt = inputs(p, lam)
    H = composite_H(p, one, X, lamt, n, npr)
    if p.is_zero(H):
        raise ArithmeticError("H vanishes")
    R = p.mod(X, H)
    for _ in range(n):
        R = p.sqrmod(R, H)
    G = p.gcd(H, p.add(R, X))
    return one, X, lamt, H, G


def route_a_dense_ref(p, field, n, npr, lam):
    """As the design's reference demo: kroots on the unsplit G."""
    one, X, lamt, H, G = a_dense_core(p, n, npr, lam)
    return closing_count(field, n, npr, lam, p.kroots(G))


def route_a_dense_berl(p, field, n, npr, lam):
    """WO-I-4 with step (6) by Berlekamp's method on G, then kroots per irreducible factor."""
    one, X, lamt, H, G = a_dense_core(p, n, npr, lam)
    ys = []
    for f in berlekamp(p, one, G):
        df = p.degree(f)
        if df >= 1:
            if n % df:
                raise ArithmeticError("FactorDegreeInconsistent")
            ys += p.kroots(f)
    return closing_count(field, n, npr, lam, ys)


def edf(p, one, X, h, i, rng):
    """Equal-degree split over F_2 of h (product of distinct degree-i irreducibles), trace map."""
    if p.degree(h) == i:
        return [h]
    dh = p.degree(h)
    while True:
        v = p.add(one, one)                       # zero, built from the lifts
        for j in range(dh):
            if rng.random() < 0.5:
                v = p.add(v, p.mod(p.shift(one, j), h))
        t, w = v, v
        for _ in range(i - 1):
            w = p.sqrmod(w, h)
            t = p.add(t, w)
        g = p.gcd(h, t)
        dg = p.degree(g)
        if 0 < dg < dh:
            return edf(p, one, X, g, i, rng) + edf(p, one, X, p.div_exact(h, g), i, rng)


def route_a_dense_ddf(p, field, n, npr, lam, seed=1):
    """WO-I-4 with step (6) by distinct-degree + equal-degree factorisation of G."""
    rng = random.Random(seed)
    one, X, lamt, H, G = a_dense_core(p, n, npr, lam)
    facs, g, i = [], G, 1
    w = p.mod(X, g) if p.degree(g) >= 1 else None
    while p.degree(g) >= 2 * i:
        w = p.sqrmod(w, g)
        h = p.gcd(g, p.add(w, X))
        if p.degree(h) > 0:
            facs += edf(p, one, X, h, i, rng)
            g = p.div_exact(g, h)
            w = p.mod(w, g)
        i += 1
    if p.degree(g) >= 1:
        facs.append(g)
    ys = []
    for f in facs:
        df = p.degree(f)
        if n % df:
            raise ArithmeticError("FactorDegreeInconsistent")
        ys += p.kroots(f)
    return closing_count(field, n, npr, lam, ys)


def route_s_berl(p, field, n, npr, lam):
    one, X, lamt = inputs(p, lam)
    cnt = 0
    for g in berlekamp(p, one, rad(p, build_L(p, one, lamt, npr))):
        dg = p.degree(g)
        if dg >= 1 and n % dg == 0:
            rs = p.kroots(g)
            if len(rs) != dg:
                raise ArithmeticError("root search failure")
            cnt += dg
    return cnt


def d3a(p, field, n, npr, lam):
    one, X, lamt = inputs(p, lam)
    L = build_L(p, one, lamt, npr)
    t = p.mod(X, L)
    for _ in range(n):
        t = p.sqrmod(t, L)
    return p.degree(p.gcd(p.add(t, X), L))


def d3b(p, field, n, npr, lam):
    one, X, lamt = inputs(p, lam)
    L = build_L(p, one, lamt, npr)
    t = p.mod(X, L)
    for _ in range(n):
        t = p.mod(p.mul(t, t), L)
    return p.degree(p.gcd(p.add(t, X), L))


def d3c(p, field, n, npr, lam):
    one, X, lamt = inputs(p, lam)
    f = rad(p, build_L(p, one, lamt, npr))
    Q = p.mat_rows(q_rows(p, one, f))
    v = p.mod(X, f)
    for _ in range(n):
        v = p.mat_apply(Q, v)
    return p.degree(p.gcd(p.add(v, X), f))


def d3d(p, field, n, npr, lam):
    one, X, lamt = inputs(p, lam)
    L = build_L(p, one, lamt, npr)
    t = p.mod(X, L)
    for s in range(n):
        if s % 2 == 0:
            holder = [copy.copy(t)]
            t = p.mod(p.mul(t, holder[0]), L)
        else:
            t = p.mulmod(t, p.lift(t.value, "X"), L)   # re-wrap of the raw value (public slot)
    return p.degree(p.gcd(p.add(t, X), L))


def d3e(p, field, n, npr, lam):
    one, X, lamt = inputs(p, lam)
    H = composite_H(p, one, X, lamt, n, npr)
    f = rad(p, build_L(p, one, lamt, npr))
    return p.degree(p.gcd(p.mod(H, f), f))


def d3f(p, field, n, npr, lam):
    one, X, lamt = inputs(p, lam)
    L = build_L(p, one, lamt, npr)
    half = 1 << (n - 1)
    w1 = p.mod(p.shift(one, half), L)
    w2 = p.mod(p.shift(X, half - 1), L)
    t = p.mulmod(w1, w2, L)
    return p.degree(p.gcd(p.add(t, X), L))


ROUTES = [("A-DENSE-ref", route_a_dense_ref, "legit"), ("A-DENSE-BERL", route_a_dense_berl, "legit"),
          ("A-DENSE-DDF", route_a_dense_ddf, "legit"), ("S-BERL", route_s_berl, "legit"),
          ("D3a", d3a, "named"), ("D3b", d3b, "named"), ("D3c", d3c, "named"), ("D3d", d3d, "named"),
          ("D3e", d3e, "named"), ("D3f", d3f, "named"),
          ("D3g", rt_new_routes.d3g, "new"), ("D3g2", rt_new_routes.d3g2, "new"), ("D3h", rt_new_routes.d3h, "new"),
          ("D3i", rt_new_routes.d3i, "new"), ("D3k", rt_new_routes.d3k, "new")]


def is_linearized(v):
    i = 0
    while v:
        if (v & 1) and i and (i & (i - 1)):
            return False
        if (v & 1) and i == 0:
            return False
        v >>= 1
        i += 1
    return True


def main():
    S = sys.argv[1]
    ref = load_ref(S + "/design_blocks/trace_audit_demo_code.py",
                   "a21f399b9dce2131c8066b71968a665a02b642ca5a7d072e88428781fb9b327d")
    cells = json.loads(sys.argv[2])
    degrees = json.loads(sys.argv[3])
    summary = {}
    rows_out = []
    for name, n, npr, P in cells:
        if n in DECLARED_N or n > 19:
            raise SystemExit("refusing declared/oversized n")
        field = Field(n, P)
        lams = [v for v in range(1 << min(degrees), 1 << (max(degrees) + 1)) if (v.bit_length() - 1) in degrees and not is_linearized(v)]
        for lam in lams:
            truth = sum(1 for x in range(field.size) if field.frob(x, npr) == field.ev(lam, x))
            Lv = (1 << (1 << npr)) ^ lam
            Rv = rad_value(Lv)
            pg = Prim(field)
            Gv = a_dense_core(pg, n, npr, lam)[4].value
            g_is_rad = (Gv == Rv)
            degG = Gv.bit_length() - 1
            for rname, fn, kind in ROUTES:
                p = Prim(field)
                try:
                    N = fn(p, field, n, npr, lam)
                    err = None
                except Exception as ex:
                    N, err = None, "%s: %s" % (type(ex).__name__, ex)
                v_rt = audit_rt(p.events, p.values, npr, lam, P, Lv, Rv)
                v_ref = audit_ref(ref, p.events, p.values, npr, lam, Lv, Rv)
                s = summary.setdefault((name, rname), {"kind": kind, "rows": 0, "N_ok": 0, "err": 0,
                                                       "flag_rt": 0, "flag_ref": 0, "rules_rt": set(), "rules_ref": set()})
                s["rows"] += 1
                s["N_ok"] += int(N == truth)
                s["err"] += int(err is not None)
                s["flag_rt"] += int(bool(v_rt))
                s["flag_ref"] += int(bool(v_ref))
                s["rules_rt"].update(x["rule"] for x in v_rt)
                s["rules_ref"].update(x["rule"] for x in v_ref)
                rows_out.append({"cell": name, "lam": format(lam, "x"), "route": rname, "N": N, "truth": truth,
                                 "err": err, "rt": sorted({x["rule"] for x in v_rt}),
                                 "ref": sorted({x["rule"] for x in v_ref}),
                                 "G_is_radL": g_is_rad, "degG": degG})
    out = {"summary": [], "rows": rows_out}
    for (cell, r), s in sorted(summary.items()):
        out["summary"].append({"cell": cell, "route": r, "kind": s["kind"], "rows": s["rows"], "N_equals_bruteforce": s["N_ok"],
                               "errors": s["err"], "rows_flagged_rt_audit": s["flag_rt"], "rows_flagged_ref_audit": s["flag_ref"],
                               "rules_rt": sorted(s["rules_rt"]), "rules_ref": sorted(s["rules_ref"])})
    print(json.dumps(out, sort_keys=True))


if __name__ == "__main__":
    main()

