"""Stand-in for r1/indep/gf2x.py's handle classes, exactly as interface.primitive_layer words them:
TPoly __slots__ (value, token), immutable, copy/deepcopy return self, no __int__/__index__/
__getitem__/__iter__, __bool__ raises, __reduce__ raises."""


class TPoly:
    __slots__ = ("value", "token")

    def __init__(self, value, token):
        object.__setattr__(self, "value", value)
        object.__setattr__(self, "token", token)

    def __setattr__(self, k, v):
        raise AttributeError("immutable")

    def __copy__(self):
        return self

    def __deepcopy__(self, memo):
        return self

    def __bool__(self):
        raise TypeError("use is_zero")

    def __reduce__(self):
        raise TypeError("no pickle")


class TMat:
    __slots__ = ("rows", "token")

    def __init__(self, rows, token):
        object.__setattr__(self, "rows", tuple(rows))
        object.__setattr__(self, "token", token)

    def __setattr__(self, k, v):
        raise AttributeError("immutable")

rt_new_routes.py.text:
"""RT new disguises as an r1/indep ROUTE module would hold them.  Static profile:
no bitwise operator, no bit_length/bit_count/to_bytes/from_bytes, no attribute whose
name starts with an underscore, no getattr/setattr/vars/__dict__, imports only an
r1.indep stand-in (rt_tpoly ~ r1.indep.gf2x).  Every F_2[X] operation inside the
trace goes through the primitive object p."""
from rt_tpoly import TPoly


def inputs(p, lam):
    return p.lift(1, "one"), p.lift(2, "X"), p.lift(lam, "lambda")


def build_L(p, one, lamt, npr):
    return p.add(p.shift(one, 2 ** npr), lamt)


def rad(p, f):
    if p.degree(f) <= 0:
        return f
    d = p.deriv(f)
    if p.is_zero(d):
        return rad(p, p.sqrt(f))
    g = p.gcd(f, d)
    w = p.div_exact(f, g)
    if p.degree(g) == 0:
        return w
    r = rad(p, g)
    return p.div_exact(p.mul(w, r), p.gcd(w, r))


def q_rows(p, one, f):
    rows = [p.mod(one, f)]
    for i in range(1, p.degree(f)):
        rows.append(p.mod(p.shift(rows[-1], 2), f))
    return rows


def d3g(p, field, n, npr, lam):
    """Modulus a MULTIPLE of L (M = L*U), n squarings of X mod M, gcd(M, U*(t+X)); deg - 2 = N."""
    one, X, lamt = inputs(p, lam)
    L = build_L(p, one, lamt, npr)
    U = p.add(p.add(p.mul(X, X), X), one)
    M = p.mul(L, U)
    t = p.mod(X, M)
    for i in range(n):
        t = p.sqrmod(t, M)
    return p.degree(p.gcd(M, p.mul(p.add(t, X), U))) - 2


def d3g2(p, field, n, npr, lam):
    """As d3g with U*L rebuilt from lambda and U (no L token exists in the trace)."""
    one, X, lamt = inputs(p, lam)
    U = p.add(p.add(p.mul(X, X), X), one)
    M = p.add(p.shift(U, 2 ** npr), p.mul(lamt, U))
    t = p.mod(X, M)
    for i in range(n):
        t = p.sqrmod(t, M)
    return p.degree(p.gcd(M, p.mul(p.add(t, X), U))) - 2


def d3h(p, field, n, npr, lam):
    """The K-side root primitive applied to L itself."""
    one, X, lamt = inputs(p, lam)
    return len(p.kroots(build_L(p, one, lamt, npr)))


# ---- off-trace coefficient-list arithmetic (no bitwise operator) ----------------
def to_list(v):
    out = []
    while v > 0:
        out.append(v % 2)
        v = v // 2
    return out


def trim(a):
    while a and a[-1] == 0:
        a = a[:-1]
    return a


def ladd(a, b):
    m = max(len(a), len(b))
    return trim([((a[i] if i < len(a) else 0) + (b[i] if i < len(b) else 0)) % 2 for i in range(m)])


def lmul(a, b):
    if not a or not b:
        return []
    out = [0] * (len(a) + len(b) - 1)
    for i, x in enumerate(a):
        if x:
            for j, y in enumerate(b):
                out[i + j] = (out[i + j] + y) % 2
    return trim(out)


def lmod(a, b):
    a = trim(list(a))
    while len(a) >= len(b):
        s = len(a) - len(b)
        for j, y in enumerate(b):
            a[s + j] = (a[s + j] + y) % 2
        a = trim(a)
    return a


def lgcd(a, b):
    a, b = trim(a), trim(b)
    while b:
        a, b = b, lmod(a, b)
    return a


def d3i(p, field, n, npr, lam):
    """I_direct computed off the trace; the trace carries only a decoy legitimate A-DENSE."""
    one, X, lamt = inputs(p, lam)
    q, r = divmod(n, npr)
    c = X
    for i in range(q + 1):
        c = p.compose(lamt, c)
    H = p.add(p.shift(one, 2 ** (npr - r)), c)
    R = p.mod(X, H)
    for i in range(n):
        R = p.sqrmod(R, H)
    p.gcd(H, p.add(R, X))                          # decoy events only (no root search)
    L = ladd([0] * (2 ** npr) + [1], to_list(lam))
    t = [0, 1]
    for i in range(n):
        t = lmod(lmul(t, t), L)
    return len(lgcd(L, ladd(t, [0, 1]))) - 1


def d3k(p, field, n, npr, lam):
    """Token forgery: squarings off the trace on the public value slot, re-wrapped as
    TPoly(value, kernel_token) without a lift event, then reduced mod L and gcd'd with L."""
    one, X, lamt = inputs(p, lam)
    L = build_L(p, one, lamt, npr)
    f = rad(p, L)
    ker = p.mat_left_kernel(p.mat_add_identity(p.mat_rows(q_rows(p, one, f))))
    ktok = ker[0].token
    t = p.mod(X, L)
    for i in range(n):
        s = int(format(t.value, "b").translate({48: "00", 49: "01"}), 2)
        t = p.mod(TPoly(s, ktok), L)
    v = t.value
    if (v // 2) % 2 == 1:
        v = v - 2
    else:
        v = v + 2
    return p.degree(p.gcd(L, TPoly(v, ktok)))


def d3e2(p, field, n, npr, lam):
    """F-1 collapse through a value-built multiple of L: D = gcd(H, U*L), then I_direct's
    squarings modulo D and a gcd; deg = N (when U does not divide H)."""
    one, X, lamt = inputs(p, lam)
    q, r = divmod(n, npr)
    c = X
    for i in range(q + 1):
        c = p.compose(lamt, c)
    H = p.add(p.shift(one, 2 ** (npr - r)), c)
    U = p.add(p.add(p.mul(X, X), X), one)
    M = p.add(p.shift(U, 2 ** npr), p.mul(lamt, U))
    D = p.gcd(H, M)
    if p.degree(D) <= 0:
        return 0
    t = p.mod(X, D)
    for i in range(n):
        t = p.sqrmod(t, D)
    return p.degree(p.gcd(D, p.add(t, X)))


def s_berl_legit(p, field, n, npr, lam):
    one, X, lamt = inputs(p, lam)
    f = rad(p, build_L(p, one, lamt, npr))
    ker = p.mat_left_kernel(p.mat_add_identity(p.mat_rows(q_rows(p, one, f))))
    k = len(ker)
    facs = [f]
    for v in ker:
        if len(facs) == k:
            break
        new = []
        for g in facs:
            if p.degree(g) <= 1:
                new.append(g)
                continue
            h = p.gcd(g, p.mod(v, g))
            dh = p.degree(h)
            if 0 < dh < p.degree(g):
                new = new + [h, p.div_exact(g, h)]
            else:
                new.append(g)
        facs = new
    cnt = 0
    for g in facs:
        dg = p.degree(g)
        if dg >= 1 and n % dg == 0:
            cnt = cnt + dg
    return cnt


def d3t(p, field, n, npr, lam, cell="syn-x", trace=True):
    """Trace-aware disguise: legitimate S-BERL whenever the call is traced (AC-7 traces
    only syn- cells with trace=True); I_direct off the trace otherwise."""
    if trace and cell.startswith("syn-"):
        return s_berl_legit(p, field, n, npr, lam)
    L = ladd([0] * (2 ** npr) + [1], to_list(lam))
    t = [0, 1]
    for i in range(n):
        t = lmod(lmul(t, t), L)
    return len(lgcd(L, ladd(t, [0, 1]))) - 1

rt_patched.py.text:
"""RT candidate local remedy for AC-7 (NOT the design's rule set): provenance classes
Hcls/Hdesc/Hres, value overrides only outside them, a modulus whitelist (R5), a kroots
input rule (R6), Lmult (value multiples of rad L) in R1-R3, and a primitive registry that
refuses forged handles (R7).  Tested only on the synthetic cells of this harness."""
import rt_trace as T


class RegPrim(T.Prim):
    """Primitive layer that refuses a handle whose (token, value) it did not issue (R7)."""
    def _p(self, v):
        o = super()._p(v)
        return o

    def _ev(self, op, ins=(), outs=(), mats=(), mats_out=(), **kw):
        for x in ins:
            if self.values.get(x.token) != x.value:
                raise PermissionError("R7 forged handle: token %d" % x.token)
        return super()._ev(op, ins, outs, mats, mats_out, **kw)


def irreducible_deg_divides(v, n):
    d = v.bit_length() - 1
    return d >= 1 and n % d == 0 and T.irreducible(v)


def audit_patched(events, values, n, n_prime, lam, P, Lv, Rv):
    q, r = divmod(n, n_prime)
    s = n_prime - r
    bound = 1 << (n_prime + 1)
    dR = Rv.bit_length() - 1
    tg, MT, viol = {}, {}, []

    def t(x):
        return tg.setdefault(x, {"L": False, "D": False, "K": False, "x": None, "cd": None,
                                 "H": False, "Hd": False, "Hr": False})

    def hset(x):
        a = t(x)
        return a["H"] or a["Hd"]

    def lcl(x):
        a = t(x)
        return (a["L"] or values.get(x) in (Lv, Rv)) and not hset(x) and not a["Hr"] and not a["K"]

    def lmult(x):
        v = values.get(x)
        a = t(x)
        if v is None or v == 0 or hset(x) or a["Hr"] or lcl(x):
            return False
        return (v.bit_length() - 1) >= dR and T.pdivmod(v, Rv)[1] == 0

    def bad(x):
        return lcl(x) or lmult(x)

    def same(a, b):
        return a == b or (values.get(a) is not None and values.get(a) == values.get(b))

    def xcomb(toks):
        tot, mod = 0, None
        for x in toks:
            e = t(x)["x"]
            if e is None:
                return None
            tot += e[0]
            if e[1] is not None:
                if mod is not None and not same(mod, e[1]):
                    return None
                mod = e[1]
        return (tot, mod)

    def flag(rule, e, why):
        viol.append({"rule": rule, "seq": e["seq"], "op": e["op"], "why": why})

    lam_tok = None
    for e in events:
        op, ins, outs = e["op"], e["ins"], e["out"]
        if op == "lift":
            lab = e.get("label")
            exp = {"one": 1, "X": 2, "lambda": lam, "modulus_P": P}.get(lab)
            if e.get("after_arith") or exp is None or values.get(outs[0]) != exp:
                flag("R0", e, "lift")
            if lab == "one":
                t(outs[0])["x"] = (0, None)
            elif lab == "X":
                t(outs[0])["x"] = (1, None)
                t(outs[0])["cd"] = 0
            elif lab == "lambda":
                lam_tok = outs[0]
        elif op == "compose":
            a, b = ins
            if a == lam_tok and t(b)["cd"] is not None:
                t(outs[0])["cd"] = t(b)["cd"] + 1
        elif op == "add":
            a, b = ins
            if (t(a)["K"] and values.get(b) == 1) or (t(b)["K"] and values.get(a) == 1):
                t(outs[0])["K"] = True
            for u, w in ((a, b), (b, a)):
                if t(u)["x"] == (1 << s, None) and t(w)["cd"] == q + 1:
                    t(outs[0])["H"] = True
                xu = t(u)["x"]
                if xu is not None and xu[1] is not None and hset(xu[1]) and t(w)["x"] == (1, None):
                    t(outs[0])["Hr"] = True
        elif op in ("mul", "sqr"):
            ops = ins if op == "mul" else [ins[0], ins[0]]
            if all(lcl(x) for x in ops):
                t(outs[0])["L"] = True
            x = xcomb(ops)
            if x is not None:
                t(outs[0])["x"] = x
        elif op == "shift":
            x = t(ins[0])["x"]
            if x is not None:
                t(outs[0])["x"] = (x[0] + e["k"], x[1])
        elif op in ("mod", "mulmod", "sqrmod"):
            m = ins[-1]
            ops = [ins[0], ins[0]] if op == "sqrmod" else ins[:-1]
            if not (hset(m) or lcl(m)):
                flag("R5", e, "reduction modulo a modulus outside {H, H-descendant, L-class}")
            if bad(m):
                for x in set(ops):
                    if not (t(x)["x"] is not None or t(x)["K"] or lcl(x)):
                        flag("R3", e, "reduction mod L-class/multiple of a non-allowed operand")
            if op == "mod" and t(ops[0])["K"] and (lcl(m) or hset(m)):
                t(outs[0])["K"] = True
            x = xcomb(ops)
            if x is not None and (op == "mod" or x[1] is None or same(x[1], m)):
                t(outs[0])["x"] = (x[0], m)
                if bad(m) and x[0] >= bound:
                    flag("R1", e, "X^%d mod L-class/multiple" % x[0])
                if hset(m):
                    t(outs[0])["Hr"] = True
        elif op == "gcd":
            a, b = ins
            for u, w in ((a, b), (b, a)):
                if bad(u) and not (lcl(w) or t(w)["D"] or t(w)["K"]):
                    flag("R2", e, "gcd of L-class/multiple with non-allowed partner")
                    break
            if hset(a) or hset(b):
                t(outs[0])["Hd"] = True
            elif lcl(a) or lcl(b):
                t(outs[0])["L"] = True
        elif op in ("div_exact", "sqrt"):
            if hset(ins[0]):
                t(outs[0])["Hd"] = True
            elif lcl(ins[0]):
                t(outs[0])["L"] = True
        elif op == "deriv":
            if lcl(ins[0]):
                t(outs[0])["D"] = True
        elif op == "mat_rows":
            xs = [t(x)["x"] for x in ins]
            ok = bool(ins) and all(x is not None and x[1] is not None for x in xs)
            if ok:
                f = xs[0][1]
                ok = (all(same(x[1], f) for x in xs) and (lcl(f) or hset(f))
                      and all(x[0] == 2 * i for i, x in enumerate(xs)) and values[f].bit_length() - 1 == len(ins))
            MT[e["mats_out"][0]] = {"Q": ok}
        elif op == "mat_add_identity":
            MT[e["mats_out"][0]] = {"QmI": bool(MT.get(e["mats"][0], {}).get("Q"))}
        elif op == "mat_left_kernel":
            if not MT.get(e["mats"][0], {}).get("QmI"):
                flag("R4", e, "kernel of a matrix other than Q - I")
            for x in outs:
                t(x)["K"] = True
        elif op in ("mat_apply", "mat_mul"):
            flag("R4", e, op)
        elif op == "kroots":
            a = ins[0]
            if not ((hset(a) or lcl(a)) and irreducible_deg_divides(values[a], n)):
                flag("R6", e, "kroots of a token that is not an irreducible split factor of degree dividing n")
    return viol

rt_static.py.text:
"""RT static check of WO-I-10 S1 to S3 (as worded) on a route module source."""
import ast, json, sys
ALLOWED = {"math", "random", "typing", "dataclasses", "functools", "itertools", "collections", "hashlib",
           "json", "os", "sys", "time", "array", "decimal", "rt_tpoly"}  # rt_tpoly stands for r1.indep.gf2x
BITOPS = (ast.BitXor, ast.BitAnd, ast.BitOr, ast.LShift, ast.RShift)
INTM = {"bit_length", "bit_count", "to_bytes", "from_bytes"}
FORBID_CALLS = {"getattr", "setattr", "vars", "__import__", "exec", "eval", "compile"}
src = open(sys.argv[1]).read()
tree = ast.parse(src)
viol = []
for node in ast.walk(tree):
    if isinstance(node, ast.Import):
        for a in node.names:
            if a.name.split(".")[0] not in ALLOWED:
                viol.append(("S1", node.lineno, a.name))
    if isinstance(node, ast.ImportFrom):
        if (node.module or "").split(".")[0] not in ALLOWED:
            viol.append(("S1", node.lineno, node.module))
    if isinstance(node, (ast.BinOp, ast.AugAssign)) and isinstance(node.op, BITOPS):
        viol.append(("S2", node.lineno, type(node.op).__name__))
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Invert):
        viol.append(("S2", node.lineno, "Invert"))
    if isinstance(node, ast.Attribute):
        if node.attr in INTM:
            viol.append(("S2", node.lineno, node.attr))
        if node.attr.startswith("_"):
            viol.append(("S3", node.lineno, node.attr))
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id in FORBID_CALLS:
        viol.append(("S3", node.lineno, node.func.id))
    if isinstance(node, ast.Name) and node.id in ("__dict__",):
        viol.append(("S3", node.lineno, node.id))
print(json.dumps({"file": sys.argv[1], "S1_S3_violations": viol, "passes_S1_S3": not viol}))

