"""Self-test of the harness's irreducibility test and rad() after the degree-1 fix (17:15:51Z)."""
import rt_trace as T
assert T.irreducible(2) and T.irreducible(3) and not T.irreducible(5) and T.irreducible(7) and T.irreducible(0x11b)


def rad_slow(f):
    res, g = 1, 2
    while f.bit_length() > 1:
        if T.irreducible(g) and T.pdivmod(f, g)[1] == 0:
            res = T.pmul(res, g)
            while T.pdivmod(f, g)[1] == 0:
                f = T.pdivmod(f, g)[0]
        g += 1
    return res


for npr in (3, 4):
    for lam in range(8, 32):
        Lv = (1 << (1 << npr)) ^ lam
        assert T.rad_value(Lv) == rad_slow(Lv), (npr, lam)
print("irreducible/rad self-tests OK")

trace_audit_demo_code.text:
"""Operand-provenance trace audit for the EXP-QSP-70b731 r1 revision design
(TASK-20261002-01d26d), DR-7: the reference primitive layer (every call is a trace
event over object-provenance tokens; TPoly objects are opaque and immutable, a copy
keeps its token, and there is no integer conversion), the reference audit rules R0
to R4 of WO-I-10 and AC-7, mock routes (legitimate A-DENSE and S-BERL, and the six
disguises D3a to D3f of REVIEW-QSP-RD-20261002-521e9d PTM-RD4), and an independent
brute-force count. Demonstration (R-C8) on synthetic cells with field degree n
outside {4, 7, 11, 12, 13, 31, 131} and n <= 19; no declared cell is used.
Importing this module executes nothing; run it through its __main__ entry.
"""
import copy
import json
import sys

DECLARED_N = frozenset((4, 7, 11, 12, 13, 31, 131))
CELLS = (
    ("syn-a-09-04", 9, 4, 0b1000010001),
    ("syn-a-10-03", 10, 3, 0b10000001001),
    ("syn-a-15-04", 15, 4, 0b1000000000000011),
)
LIFT_LABELS = ("one", "X", "lambda")


def p_mul(a, b):
    out = 0
    while b:
        if b & 1:
            out ^= a
        a <<= 1
        b >>= 1
    return out


def p_divmod(a, b):
    if b == 0:
        raise ZeroDivisionError("polynomial division by zero")
    quotient = 0
    db = b.bit_length()
    while a.bit_length() >= db:
        shift = a.bit_length() - db
        quotient ^= 1 << shift
        a ^= b << shift
    return quotient, a


def p_gcd(a, b):
    while b:
        a, b = b, p_divmod(a, b)[1]
    return a


def p_deriv(a):
    out = 0
    i = 1
    a >>= 1
    while a:
        if a & 1 and i % 2 == 1:
            out ^= 1 << (i - 1)
        a >>= 1
        i += 1
    return out


def p_sqrt(a):
    out = 0
    i = 0
    while a:
        if a & 1:
            if i % 2:
                raise ArithmeticError("not a square")
            out ^= 1 << (i // 2)
        a >>= 1
        i += 1
    return out


def p_compose(lam, a):
    acc = 0
    for i in range(lam.bit_length() - 1, -1, -1):
        acc = p_mul(acc, a) ^ ((lam >> i) & 1)
    return acc


def left_kernel(rows, m):
    """Left kernel of an m x m F_2 matrix given as m row integers (bit j = column j)."""
    buckets = {}
    for i, row in enumerate(rows):
        aug = (row << m) | (1 << i)
        buckets.setdefault(aug.bit_length(), []).append(aug)
    for top in range(2 * m, m, -1):
        group = buckets.pop(top, None)
        if not group:
            continue
        pivot = group[0]
        for row in group[1:]:
            row ^= pivot
            buckets.setdefault(row.bit_length(), []).append(row)
    return [row for key in sorted(buckets) for row in buckets[key]]


class Field:
    """K = F_2[z]/(P) by log tables, built after a Rabin irreducibility test."""

    def __init__(self, n, modulus):
        self.n, self.P = n, modulus
        self.size = 1 << n
        self.order = self.size - 1
        self.irreducible = self._rabin()
        if not self.irreducible:
            raise ValueError("modulus not irreducible")
        primes = self._prime_factors(self.order)
        self.generator = next(g for g in range(2, self.size)
                              if all(self._pow(g, self.order // p) != 1 for p in primes))
        self.exp = [0] * (2 * self.order)
        self.log = [0] * self.size
        x = 1
        for e in range(self.order):
            self.exp[e] = self.exp[e + self.order] = x
            self.log[x] = e
            x = self._slow_mul(x, self.generator)
        self.exp_ok = x == 1 and len(set(self.exp[:self.order])) == self.order

    def _slow_mul(self, x, y):
        return p_divmod(p_mul(x, y), self.P)[1]

    def _pow(self, x, e):
        result = 1
        while e:
            if e & 1:
                result = self._slow_mul(result, x)
            x = self._slow_mul(x, x)
            e >>= 1
        return result

    @staticmethod
    def _prime_factors(m):
        primes, d = [], 2
        while d * d <= m:
            if m % d == 0:
                primes.append(d)
                while m % d == 0:
                    m //= d
            d += 1
        if m > 1:
            primes.append(m)
        return primes

    def _rabin(self):
        def frob_x(k):
            x = 2
            for _ in range(k):
                x = self._slow_mul(x, x)
            return x
        if frob_x(self.n) != 2:
            return False
        return all(p_gcd(self.P, frob_x(self.n // p) ^ 2) == 1 for p in self._prime_factors(self.n))

    def mul(self, x, y):
        if x == 0 or y == 0:
            return 0
        return self.exp[self.log[x] + self.log[y]]

    def frob(self, x, k):
        for _ in range(k):
            x = self.mul(x, x)
        return x

    def eval_f2(self, poly, x):
        if x == 0:
            return poly & 1
        lx = self.log[x]
        acc = 0
        i = 0
        while poly:
            if poly & 1:
                acc ^= self.exp[(i * lx) % self.order]
            poly >>= 1
            i += 1
        return acc

    def roots(self, poly):
        if poly == 0:
            raise ArithmeticError("roots of the zero polynomial")
        return [x for x in range(self.size) if self.eval_f2(poly, x) == 0]


class TPoly:
    """Opaque, immutable polynomial handle carrying an object-provenance token."""
    __slots__ = ("_v", "_tok")

    def __init__(self, value, tok):
        object.__setattr__(self, "_v", value)
        object.__setattr__(self, "_tok", tok)

    def __setattr__(self, name, value):
        raise AttributeError("TPoly is immutable")

    def __copy__(self):
        return self

    def __deepcopy__(self, memo):
        return self

    def __reduce__(self):
        raise TypeError("TPoly cannot be pickled or re-wrapped")

    def __bool__(self):
        raise TypeError("use the is_zero primitive")


class TMat:
    __slots__ = ("_rows", "_tok")

    def __init__(self, rows, tok):
        object.__setattr__(self, "_rows", tuple(rows))
        object.__setattr__(self, "_tok", tok)

    def __setattr__(self, name, value):
        raise AttributeError("TMat is immutable")


class Prim:
    """The only route-facing arithmetic; every call appends one trace event."""

    def __init__(self, field):
        self.field = field
        self.events = []
        self.values = {}
        self.matrix_rows = {}
        self._next = 1
        self._arith = False

    def _token(self):
        tok = self._next
        self._next += 1
        return tok

    def _poly(self, value):
        tok = self._token()
        self.values[tok] = value
        return TPoly(value, tok)

    def _mat(self, rows):
        tok = self._token()
        self.matrix_rows[tok] = list(rows)
        return TMat(rows, tok)

    def _record(self, op, ins=(), outs=(), mats=(), mats_out=(), **extra):
        if op != "lift":
            self._arith = True
        event = {"op": op, "ins": [x._tok for x in ins], "out": [x._tok for x in outs],
                 "mats": [x._tok for x in mats], "mats_out": [x._tok for x in mats_out]}
        event.update(extra)
        self.events.append(event)

    def lift(self, value, label):
        out = self._poly(value)
        self._record("lift", outs=[out], label=label, after_arith=self._arith)
        return out

    def add(self, a, b):
        out = self._poly(a._v ^ b._v)
        self._record("add", ins=[a, b], outs=[out])
        return out

    def mul(self, a, b):
        out = self._poly(p_mul(a._v, b._v))
        self._record("mul", ins=[a, b], outs=[out])
        return out

    def shift(self, a, k):
        out = self._poly(a._v << k)
        self._record("shift", ins=[a], outs=[out], k=k)
        return out

    def mod(self, a, m):
        out = self._poly(p_divmod(a._v, m._v)[1])
        self._record("mod", ins=[a, m], outs=[out])
        return out

    def mulmod(self, a, b, m):
        out = self._poly(p_divmod(p_mul(a._v, b._v), m._v)[1])
        self._record("mulmod", ins=[a, b, m], outs=[out])
        return out

    def sqrmod(self, a, m):
        out = self._poly(p_divmod(p_mul(a._v, a._v), m._v)[1])
        self._record("sqrmod", ins=[a, m], outs=[out])
        return out

    def gcd(self, a, b):
        out = self._poly(p_gcd(a._v, b._v))
        self._record("gcd", ins=[a, b], outs=[out])
        return out

    def div_exact(self, a, b):
        quotient, remainder = p_divmod(a._v, b._v)
        if remainder:
            raise ArithmeticError("inexact division")
        out = self._poly(quotient)
        self._record("div_exact", ins=[a, b], outs=[out])
        return out

    def deriv(self, a):
        out = self._poly(p_deriv(a._v))
        self._record("deriv", ins=[a], outs=[out])
        return out

    def sqrt(self, a):
        out = self._poly(p_sqrt(a._v))
        self._record("sqrt", ins=[a], outs=[out])
        return out

    def compose(self, lam, a):
        out = self._poly(p_compose(lam._v, a._v))
        self._record("compose", ins=[lam, a], outs=[out])
        return out

    def degree(self, a):
        self._record("degree", ins=[a])
        return a._v.bit_length() - 1

    def is_zero(self, a):
        self._record("is_zero", ins=[a])
        return a._v == 0

    def mat_rows(self, rows):
        out = self._mat([row._v for row in rows])
        self._record("mat_rows", ins=rows, mats_out=[out])
        return out

    def mat_add_identity(self, M):
        out = self._mat([row ^ (1 << i) for i, row in enumerate(M._rows)])
        self._record("mat_add_identity", mats=[M], mats_out=[out])
        return out

    def mat_left_kernel(self, M):
        outs = [self._poly(v) for v in left_kernel(list(M._rows), len(M._rows))]
        self._record("kernel", mats=[M], outs=outs)
        return outs

    def mat_apply(self, M, v):
        value, c, i = 0, v._v, 0
        while c:
            if c & 1:
                value ^= M._rows[i]
            c >>= 1
            i += 1
        out = self._poly(value)
        self._record("mat_apply", ins=[v], mats=[M], outs=[out])
        return out

    def kroots(self, a):
        self._record("kroots", ins=[a])
        return self.field.roots(a._v)


def inputs(prim, lam_value):
    return prim.lift(1, "one"), prim.lift(2, "X"), prim.lift(lam_value, "lambda")


def build_L(prim, one, lam, n_prime):
    return prim.add(prim.shift(one, 1 << n_prime), lam)


def rad(prim, f):
    if prim.degree(f) <= 0:
        return f
    d = prim.deriv(f)
    if prim.is_zero(d):
        return rad(prim, prim.sqrt(f))
    g = prim.gcd(f, d)
    w = prim.div_exact(f, g)
    if prim.degree(g) == 0:
        return w
    r = rad(prim, g)
    return prim.div_exact(prim.mul(w, r), prim.gcd(w, r))


def q_rows(prim, one, f):
    rows = [prim.mod(one, f)]
    for _ in range(1, prim.degree(f)):
        rows.append(prim.mod(prim.shift(rows[-1], 2), f))
    return rows


def berlekamp_factors(prim, one, f):
    kernel = prim.mat_left_kernel(prim.mat_add_identity(prim.mat_rows(q_rows(prim, one, f))))
    k = len(kernel)
    factors = [f]
    for v in kernel:
        if len(factors) == k:
            break
        new = []
        for g in factors:
            if prim.degree(g) <= 1:
                new.append(g)
                continue
            h = prim.gcd(g, prim.mod(v, g))
            dh = prim.degree(h)
            if 0 < dh < prim.degree(g):
                new.extend((h, prim.div_exact(g, h)))
            else:
                new.append(g)
        factors = new
    if len(factors) != k:
        raise ArithmeticError("Berlekamp split incomplete")
    return factors


def composite_H(prim, one, X, lam, n, n_prime):
    q, r = divmod(n, n_prime)
    composite = X
    for _ in range(q + 1):
        composite = prim.compose(lam, composite)
    return prim.add(prim.shift(one, 1 << (n_prime - r)), composite)


def route_a_dense(prim, field, n, n_prime, lam_value):
    """Derivation (A): K-roots of H via gcd(H, Y^(2^n) - Y), then the closing test."""
    q, r = divmod(n, n_prime)
    one, X, lam = inputs(prim, lam_value)
    H = composite_H(prim, one, X, lam, n, n_prime)
    if prim.is_zero(H):
        raise ArithmeticError("H vanishes")
    R = prim.mod(X, H)
    for _ in range(n):
        R = prim.sqrmod(R, H)
    G = prim.gcd(H, prim.add(R, X))
    count = 0
    for y in prim.kroots(G):
        x = y
        for _ in range(q):
            x = field.eval_f2(lam_value, x)
        if field.frob(x, r) == y and field.frob(x, n_prime) == field.eval_f2(lam_value, x):
            count += 1
    return count


def route_s_berl(prim, field, n, n_prime, lam_value):
    """S-BERL: distinct-factor degrees of L by Berlekamp's kernel method."""
    one, X, lam = inputs(prim, lam_value)
    count = 0
    for g in berlekamp_factors(prim, one, rad(prim, build_L(prim, one, lam, n_prime))):
        dg = prim.degree(g)
        if n % dg == 0:
            if len(prim.kroots(g)) != dg:
                raise ArithmeticError("root search failure")
            count += dg
    return count


def route_d3a(prim, field, n, n_prime, lam_value):
    """D3a: repeated squaring modulo L with a squaring-named primitive, then gcd with L."""
    one, X, lam = inputs(prim, lam_value)
    L = build_L(prim, one, lam, n_prime)
    t = prim.mod(X, L)
    for _ in range(n):
        t = prim.sqrmod(t, L)
    return prim.degree(prim.gcd(prim.add(t, X), L))


def route_d3b(prim, field, n, n_prime, lam_value):
    """D3b: the product of a residue with itself under generic names, then reduction modulo L."""
    one, X, lam = inputs(prim, lam_value)
    L = build_L(prim, one, lam, n_prime)
    t = prim.mod(X, L)
    for _ in range(n):
        t = prim.mod(prim.mul(t, t), L)
    return prim.degree(prim.gcd(prim.add(t, X), L))


def route_d3c(prim, field, n, n_prime, lam_value):
    """D3c: powers of S-BERL's own Frobenius matrix Q applied to X, then a gcd with rad L."""
    one, X, lam = inputs(prim, lam_value)
    f = rad(prim, build_L(prim, one, lam, n_prime))
    Q = prim.mat_rows(q_rows(prim, one, f))
    v = prim.mod(X, f)
    for _ in range(n):
        v = prim.mat_apply(Q, v)
    return prim.degree(prim.gcd(prim.add(v, X), f))


def route_d3d(prim, field, n, n_prime, lam_value):
    """D3d: the residue copied (copy, list element) or re-wrapped from its raw value, times itself."""
    one, X, lam = inputs(prim, lam_value)
    L = build_L(prim, one, lam, n_prime)
    t = prim.mod(X, L)
    for step in range(n):
        if step % 2 == 0:
            holder = [copy.copy(t)]
            t = prim.mod(prim.mul(t, holder[0]), L)
        else:
            raw = object.__getattribute__(t, "_v")
            t = prim.mulmod(t, prim.lift(raw, "X"), L)
    return prim.degree(prim.gcd(prim.add(t, X), L))


def route_d3e(prim, field, n, n_prime, lam_value):
    """D3e: a route labelled derivation (A) that reduces H modulo rad L before its gcd."""
    one, X, lam = inputs(prim, lam_value)
    H = composite_H(prim, one, X, lam, n, n_prime)
    f = rad(prim, build_L(prim, one, lam, n_prime))
    return prim.degree(prim.gcd(prim.mod(H, f), f))


def route_d3f(prim, field, n, n_prime, lam_value):
    """D3f: X^(2^n) mod L as a product of two table entries, never squaring a named residue."""
    one, X, lam = inputs(prim, lam_value)
    L = build_L(prim, one, lam, n_prime)
    half = 1 << (n - 1)
    w1 = prim.mod(prim.shift(one, half), L)
    w2 = prim.mod(prim.shift(X, half - 1), L)
    t = prim.mulmod(w1, w2, L)
    return prim.degree(prim.gcd(prim.add(t, X), L))


ROUTES = (
    ("A-DENSE", route_a_dense, "legitimate"),
    ("S-BERL", route_s_berl, "legitimate"),
    ("D3a", route_d3a, "disguise"),
    ("D3b", route_d3b, "disguise"),
    ("D3c", route_d3c, "disguise"),
    ("D3d", route_d3d, "disguise"),
    ("D3e", route_d3e, "disguise"),
    ("D3f", route_d3f, "disguise"),
)


def aud_rad(f):
    """Squarefree part of f by trial division (written apart from the routes' rad)."""
    result = 1
    g = 2
    while f.bit_length() > 1 and 2 * (g.bit_length() - 1) <= f.bit_length() - 1:
        if p_divmod(f, g)[1] == 0:
            result = p_mul(result, g)
            while p_divmod(f, g)[1] == 0:
                f = p_divmod(f, g)[0]
        g += 1
    if f.bit_length() > 1:
        result = p_mul(result, f)
    return result


def audit(events, values, n_prime, lam_value, L_value, radL_value):
    """Rules R0 to R4 of WO-I-10 on one route's event list."""
    bound = 1 << (n_prime + 1)
    tags, mtags, violations = {}, {}, []

    def tag(tok):
        return tags.setdefault(tok, {"lfac": False, "deriv": False, "kern": False,
                                     "xexp": None, "xmod": None})

    def lfac(tok):
        return tag(tok)["lfac"] or values.get(tok) in (L_value, radL_value)

    def same(m1, m2):
        return m1 == m2 or values.get(m1) == values.get(m2)

    def combine(toks):
        total, modulus = 0, None
        for tok in toks:
            t = tag(tok)
            if t["xexp"] is None:
                return None, None
            total += t["xexp"]
            if t["xmod"] is not None:
                if modulus is not None and not same(modulus, t["xmod"]):
                    return None, None
                modulus = t["xmod"]
        return total, modulus

    def flag(rule, index, op, detail):
        violations.append({"rule": rule, "event": index, "op": op, "detail": detail})

    for index, event in enumerate(events):
        op, ins, outs = event["op"], event["ins"], event["out"]
        if op == "lift":
            label = event.get("label")
            expected = {"one": 1, "X": 2, "lambda": lam_value}.get(label)
            if event.get("after_arith") or label not in LIFT_LABELS or values.get(outs[0]) != expected:
                flag("R0", index, op, "lift %r after arithmetic or of an unexpected value" % label)
            elif label in ("one", "X"):
                tag(outs[0])["xexp"] = 0 if label == "one" else 1
        elif op == "add":
            a, b = ins
            if (tag(a)["kern"] and values.get(b) == 1) or (tag(b)["kern"] and values.get(a) == 1):
                tag(outs[0])["kern"] = True
        elif op == "mul":
            if all(lfac(tok) for tok in ins):
                tag(outs[0])["lfac"] = True
            exponent, modulus = combine(ins)
            if exponent is not None:
                tag(outs[0])["xexp"], tag(outs[0])["xmod"] = exponent, modulus
        elif op == "shift":
            t = tag(ins[0])
            if t["xexp"] is not None:
                tag(outs[0])["xexp"], tag(outs[0])["xmod"] = t["xexp"] + event["k"], t["xmod"]
        elif op in ("mod", "mulmod", "sqrmod"):
            m = ins[-1]
            operands = [ins[0], ins[0]] if op == "sqrmod" else ins[:-1]
            if lfac(m):
                for tok in set(operands):
                    t = tag(tok)
                    if not (t["xexp"] is not None or t["kern"] or lfac(tok)):
                        flag("R3", index, op, "reduction modulo an L-class modulus of a token outside the allowed classes")
            if op == "mod" and tag(operands[0])["kern"] and lfac(m):
                tag(outs[0])["kern"] = True
            exponent, modulus = combine(operands)
            if exponent is not None and (modulus is None or same(modulus, m)):
                tag(outs[0])["xexp"], tag(outs[0])["xmod"] = exponent, m
                if lfac(m) and exponent >= bound:
                    flag("R1", index, op, "residue X^%d modulo an L-class modulus (bound %d)" % (exponent, bound))
        elif op == "gcd":
            a, b = ins
            if lfac(a) or lfac(b):
                for tok, other in ((a, b), (b, a)):
                    o = tag(other)
                    if lfac(tok) and not (lfac(other) or o["deriv"] or o["kern"]):
                        flag("R2", index, op, "gcd of an L-class polynomial with a partner outside {L-class, derivative, kernel}")
                        break
                tag(outs[0])["lfac"] = True
        elif op in ("div_exact", "sqrt"):
            if lfac(ins[0]):
                tag(outs[0])["lfac"] = True
        elif op == "deriv":
            if lfac(ins[0]):
                tag(outs[0])["deriv"] = True
        elif op == "mat_rows":
            mods = [tag(tok)["xmod"] for tok in ins]
            is_q = (bool(ins) and all(mod is not None for mod in mods)
                    and all(tag(tok)["xexp"] == 2 * i for i, tok in enumerate(ins))
                    and all(same(mods[0], mod) for mod in mods) and lfac(mods[0])
                    and values[mods[0]].bit_length() - 1 == len(ins))
            mtags[event["mats_out"][0]] = {"Q": is_q, "mod": mods[0] if is_q else None}
        elif op == "mat_add_identity":
            mtags[event["mats_out"][0]] = {"QmI": bool(mtags.get(event["mats"][0], {}).get("Q"))}
        elif op == "kernel":
            if not mtags.get(event["mats"][0], {}).get("QmI"):
                flag("R4", index, op, "kernel of a matrix other than Q - I")
            for tok in outs:
                tag(tok)["kern"] = True
        elif op == "mat_apply":
            flag("R4", index, op, "application of a matrix to a vector")
            source = mtags.get(event["mats"][0], {})
            v = tag(ins[0])
            if source.get("Q") and v["xexp"] is not None and (v["xmod"] is None or same(v["xmod"], source["mod"])):
                tag(outs[0])["xexp"], tag(outs[0])["xmod"] = 2 * v["xexp"], source["mod"]
                if 2 * v["xexp"] >= bound:
                    flag("R1", index, op, "residue X^%d modulo an L-class modulus via the Frobenius matrix" % (2 * v["xexp"]))
        elif op == "mat_mul":
            flag("R4", index, op, "matrix product")
    return violations


def is_linearized(p):
    if p == 0:
        return False
    i = 0
    while p:
        if p & 1 and (i == 0 or i & (i - 1)):
            return False
        p >>= 1
        i += 1
    return True


def object_properties():
    t = TPoly(5, 0)
    report = {}
    for name, action in (("int", lambda: int(t)), ("index", lambda: t[0]), ("bool", lambda: bool(t)),
                         ("setattr", lambda: setattr(t, "_v", 7)), ("reduce", lambda: t.__reduce__())):
        try:
            action()
            report[name] = "allowed"
        except (TypeError, AttributeError) as error:
            report[name] = "refused: %s" % type(error).__name__
    report["copy_is_same_object"] = copy.copy(t) is t
    report["deepcopy_is_same_object"] = copy.deepcopy(t) is t
    report["list_element_is_same_object"] = [copy.copy(t)][0] is t
    return report


def main():
    properties = object_properties()
    print(json.dumps({"object_properties": properties}, sort_keys=True))
    all_met = all(value is True or str(value).startswith("refused") for value in properties.values())
    for name, n, n_prime, modulus in CELLS:
        if n in DECLARED_N or n > 19:
            raise SystemExit("refusing a declared or oversized field degree")
        field = Field(n, modulus)
        print(json.dumps({"cell": name, "n": n, "n_prime": n_prime, "modulus_hex": format(modulus, "x"),
                          "modulus_irreducible": field.irreducible, "generator": field.generator,
                          "exp_table_ok": field.exp_ok}, sort_keys=True))
        all_met = all_met and field.exp_ok
        stats = {route: {"rows": 0, "count_mismatches": 0, "errors": 0, "rows_flagged": 0,
                         "rules": set(), "example": None} for route, _, _ in ROUTES}
        for lam in [p for p in range(8, 32) if not is_linearized(p)]:
            truth = sum(1 for x in range(field.size)
                        if field.frob(x, n_prime) == field.eval_f2(lam, x))
            L_value = (1 << (1 << n_prime)) ^ lam
            radL_value = aud_rad(L_value)
            for route, function, _ in ROUTES:
                prim = Prim(field)
                record = stats[route]
                record["rows"] += 1
                try:
                    count = function(prim, field, n, n_prime, lam)
                except (ArithmeticError, IndexError, ZeroDivisionError):
                    count = None
                    record["errors"] += 1
                if count != truth:
                    record["count_mismatches"] += 1
                found = audit(prim.events, prim.values, n_prime, lam, L_value, radL_value)
                if found:
                    record["rows_flagged"] += 1
                    record["rules"].update(item["rule"] for item in found)
                    if record["example"] is None:
                        record["example"] = found[0]
        for route, _, kind in ROUTES:
            record = stats[route]
            if kind == "legitimate":
                met = (record["count_mismatches"] == 0 and record["errors"] == 0
                       and record["rows_flagged"] == 0)
                expectation = "brute force's N on every row and no row flagged"
            else:
                met = (record["count_mismatches"] == 0 and record["errors"] == 0
                       and record["rows_flagged"] == record["rows"])
                expectation = "brute force's N (I_direct's quantity) on every row and every row flagged"
            all_met = all_met and met
            print(json.dumps({"cell": name, "route": route, "kind": kind, "rows": record["rows"],
                              "count_mismatches": record["count_mismatches"], "errors": record["errors"],
                              "rows_flagged": record["rows_flagged"], "rules_fired": sorted(record["rules"]),
                              "first_violation": record["example"], "expectation": expectation,
                              "met": met}, sort_keys=True))
    print(json.dumps({"summary": "trace-audit", "all_expectations_met": all_met}))
    return 0 if all_met else 1


if __name__ == "__main__":
    sys.exit(main())

